const CHAPTERS=[{"id":"permit","name":"Permits & Licensing","icon":"🪪","src":"Handbook: Driver Education & Permits","qs":[{"id":"per-1gzug3d","q":"What is the minimum age to get a Utah entry-level learner permit?","a":"15","o":["15","14","16","17"],"why":"Utah's entry-level learner permit starts at age 15. The 6-month learner permit starts at 16."},{"id":"per-1rubvg5","q":"A 16 or 17 year old needs to hold a learner permit for how long before getting a license?","a":"At least six months","o":["At least six months","At least 90 days","At least twelve months","At least thirty days"],"why":"Ages 16 and 17 must hold the permit six months and finish driver education."},{"id":"per-1c8b9qg","q":"Utah teens ages 15 to 18 must drive how many hours with a parent or guardian before licensing?","a":"40 hours, with 10 after sunset","o":["40 hours, with 10 after sunset","40 hours, with 20 after sunset","50 hours, with 10 after sunset","30 hours, with 10 after sunset"],"why":"The handbook requires 40 hours of driving, 10 of them after sunset."},{"id":"per-ivaaw9","q":"Which of these may supervise a minor learner permit driver under the 2026 change in the law?","a":"A licensed stepparent or foster parent","o":["A licensed stepparent or foster parent","A licensed older sibling who is 18","Any licensed friend who is 18","A licensed neighbor with no written permission"],"why":"SB 22 (2026) lets a stepparent or foster parent supervise a minor permit holder."},{"id":"per-18dqal5","q":"How must the learner permit be carried while you drive?","a":"In your immediate possession","o":["In your immediate possession","Stored in the trunk of the car","Left at home with a parent","Carried only when driving at night"],"why":"The permit must be in your immediate possession whenever you drive."},{"id":"per-13ij65x","q":"What does a Utah provisional license tell you about the holder?","a":"The driver is under 21","o":["The driver is under 21","The driver is new to Utah","The driver is under 18","The driver failed the first road test"],"why":"A provisional license is issued to every Utah driver under age 21."},{"id":"per-1pygyvk","q":"What is the minimum age for an original regular Utah Class D license?","a":"16","o":["16","15","17","18"],"why":"Class D, the regular car license, has a minimum age of 16."},{"id":"per-ir1der","q":"Which license class covers a regular passenger car?","a":"Class D","o":["Class D","Class A","Class B","Class C"],"why":"Class D covers vehicles that are not Class A, B, C, or a motorcycle."},{"id":"per-1qb5lhb","q":"A 19 year old with no license and no driver education must hold a learner permit for how long?","a":"90 days","o":["90 days","6 months","30 days","1 year"],"why":"Age 19 and older can skip driver education by holding the permit 90 days and logging 40 hours."},{"id":"per-huiyvm","q":"A first-time applicant who is 18 must do what?","a":"Finish an approved driver education course","o":["Finish an approved driver education course","Hold a permit for six full months","Hold a permit for at least 90 days","Pass a second written knowledge test"],"why":"At 18 there is no holding period, but driver education is required."},{"id":"per-100brcq","q":"How many behind-the-wheel hours are part of a Utah driver education course?","a":"6 hours","o":["6 hours","10 hours","4 hours","12 hours"],"why":"The course includes 6 hours behind the wheel plus classroom and observation time."},{"id":"per-1ib3fe","q":"Which endorsement lets you ride a motorcycle?","a":"M","o":["M","H","S","T"],"why":"The M endorsement covers motorcycles."},{"id":"per-1se74e4","q":"A 16 year old with a full license may not drive during which hours without a licensed adult 21 or older?","a":"12:00 a.m. to 5:00 a.m.","o":["12:00 a.m. to 5:00 a.m.","10:00 p.m. to 5:00 a.m.","11:00 p.m. to 6:00 a.m.","9:00 p.m. to 4:00 a.m."],"why":"Age 16 drivers have a midnight to 5 a.m. limit, with exceptions like work, school events, and emergencies."},{"id":"per-1cd7rso","q":"For the first six months, a licensed 16 year old may carry passengers who are:","a":"Immediate family only","o":["Immediate family only","Any friends","Anyone age 21 or younger","Anyone with written permission"],"why":"The passenger limit is immediate family until six months after the license is issued, with exceptions."},{"id":"per-58wl8o","q":"A visitor has a valid license from another state and is at least 16. In Utah, they may:","a":"Drive without a Utah license","o":["Drive without a Utah license","Drive only with a Utah permit","Drive only for 30 days","Drive only with a Utah driver in the car"],"why":"Out-of-state licensed drivers 16 and older may drive in Utah."},{"id":"per-1j0ekyg","q":"How soon must a Class D driver tell the division after moving to a new address?","a":"Within 10 days","o":["Within 10 days","Within 30 days","Within 90 days","At the next renewal"],"why":"Class D drivers notify the division within 10 days of an address change."},{"id":"per-12edkr9","q":"A 17 year old has held a learner permit for 4 months and has finished driver education. Can the teen get a regular license now?","a":"No, the permit must be held at least six months","o":["No, the permit must be held at least six months","Yes, finishing driver education replaces the waiting time","Yes, if the teen has logged 40 driving hours","No, the teen must wait until turning 18"],"why":"Ages 16 and 17 must hold the permit at least six months and finish driver education."},{"id":"per-tnfl69","q":"How many classroom hours does a Utah high school driver education course require?","a":"27 hours","o":["27 hours","18 hours","30 hours","36 hours"],"why":"High school courses use 27 classroom hours. Private schools use 18 and online or home study uses 30."},{"id":"per-v22yoo","q":"A commercial or private driving school course has how many classroom hours?","a":"18 hours","o":["18 hours","27 hours","30 hours","12 hours"],"why":"Commercial and private schools teach 18 classroom hours. High schools use 27."},{"id":"per-oc8s9q","q":"An approved online or home study driver education course has how many classroom hours?","a":"30 hours","o":["30 hours","27 hours","18 hours","40 hours"],"why":"Utah approved online and home study courses are 30 classroom hours."},{"id":"per-1vq5fni","q":"How long is an entry-level learner permit valid?","a":"18 months","o":["18 months","6 months","12 months","24 months"],"why":"An entry-level learner permit lasts 18 months, and so does the passing written test score."},{"id":"per-1g7ieem","q":"A 15 year old with a learner permit is driving. Who may ride in the front passenger seat?","a":"A licensed adult 21 or older with written permission from a parent","o":["A licensed adult 21 or older with written permission from a parent","A licensed friend who is 18 with a parent's phone call","Any licensed adult, even with no paperwork or permission","An older brother who has only a learner permit himself"],"why":"The supervisor must be a parent, guardian, instructor, or a licensed adult 21 or older with written parent authorization."},{"id":"per-8xcbts","q":"A teen's parent does not have a driver license. Who may supervise the teen's learner permit driving?","a":"A licensed adult 21 or older who carries the parent's written permission","o":["A licensed adult 21 or older who carries the parent's written permission","Any licensed driver who is 18","No one, so the teen has to wait until 18","A licensed adult 21 or older with no written permission"],"why":"If the parent is not a licensed driver, another adult may supervise but must carry the parent's written authorization."},{"id":"per-1kavp7l","q":"An 18 year old with a learner permit is driving. Who must sit in the front seat?","a":"A licensed driver 21 or older","o":["A licensed driver 21 or older","A licensed driver 18 or older","A parent only","Nobody, if it is daytime"],"why":"At 18 and older, a permit holder needs a licensed driver 21 or older in the front seat."},{"id":"per-ztufb8","q":"A 16 year old with a license may drive between midnight and 5 a.m. only when:","a":"A licensed driver 21 or older is in the front seat","o":["A licensed driver 21 or older is in the front seat","A licensed friend who is 18 rides along","The teen stays on main roads","A parent knows where the teen is going"],"why":"The midnight to 5 a.m. limit has exceptions such as a licensed driver 21 or older in front, work, school activities, and emergencies."},{"id":"per-7mu4nn","q":"A 16 year old with a license is driving home from work at 1 a.m. Is this allowed?","a":"Yes, driving to or from work is an exception","o":["Yes, driving to or from work is an exception","No, the midnight limit has no exceptions","No, only school events are exceptions","Yes, but only on the freeway"],"why":"Work, school activities, farm work, emergencies, or a licensed driver 21 or older in front are exceptions to the midnight limit."},{"id":"per-fwy7op","q":"A 16 year old got a license two months ago. Which passenger may ride with the teen when no adult 21 or older is along?","a":"The teen's sister","o":["The teen's sister","A best friend from school","A teammate going to practice","A neighbor who is 17"],"why":"For the first six months, passengers must be immediate family unless an exception applies."},{"id":"per-ob87mb","q":"When does the immediate-family passenger limit for a new 16 year old driver end?","a":"Six months after the license is issued","o":["Six months after the license is issued","At age 17","After 90 days","One year after the license is issued"],"why":"The limit lasts until six months after the license is issued."},{"id":"per-1h17uma","q":"A provisional Class D license, for drivers under 21, expires on the birthday how many years after issue?","a":"Five years","o":["Five years","Eight years","Three years","Ten years"],"why":"Provisional licenses expire five years after issue. Regular licenses for adults last eight years."},{"id":"per-erc8gn","q":"A regular Class D license for a driver 21 or older expires on the birthday how many years after issue?","a":"Eight years","o":["Eight years","Five years","Four years","Ten years"],"why":"Regular adult licenses last eight years."},{"id":"per-zwp7ad","q":"How early can you renew your Utah license?","a":"Up to six months before it expires","o":["Up to six months before it expires","Up to one month before it expires","Only in the month it expires","Up to two years before it expires"],"why":"You can schedule an online renewal appointment up to six months ahead."},{"id":"per-1nfev2b","q":"A visitor with a valid license from another state may drive in Utah for up to:","a":"Six months","o":["Six months","30 days","90 days","One year"],"why":"Visitors with a valid out-of-state or out-of-country license may drive in Utah for up to six months."},{"id":"per-1di6ii","q":"Can someone use an out-of-state learner permit to drive in Utah?","a":"No, out-of-state learner permits do not allow driving here","o":["No, out-of-state learner permits do not allow driving here","Yes, for up to six months with a licensed adult","Yes, if a Utah resident rides along in the car","Yes, but only in daylight on local streets"],"why":"Out-of-state learner permits are not valid for driving in Utah."},{"id":"per-1gpypnd","q":"Which person is treated as a Utah resident who needs a Utah license?","a":"Someone who stays in Utah six months or more in a calendar year","o":["Someone who stays in Utah six months or more in a calendar year","Someone visiting Utah for a summer weekend","Someone passing through on a road trip","Someone on a short work assignment from another state"],"why":"Staying six months or more in a year makes you a resident. Temporary assignments do not count."},{"id":"per-20gp1w","q":"Which person may NOT be given a Utah driver license?","a":"Someone whose license is suspended in another state","o":["Someone whose license is suspended in another state","A 16 year old who finished driver education and six months with a permit","A new Utah resident with a valid out-of-state license","Someone who wears glasses to drive"],"why":"You cannot be licensed in Utah if your license is denied, suspended, or revoked in any state."},{"id":"per-138qdx2","q":"A teen moves to Utah with an out-of-state online driver education certificate. Will Utah accept it?","a":"No, out-of-state online certificates are not accepted","o":["No, out-of-state online certificates are not accepted","Yes, if it shows at least 27 classroom hours","Yes, if a parent signs it before a notary","Yes, but it only counts for a learner permit"],"why":"Utah does not accept out-of-state online or home study driver education. Missing hours can be made up at an approved Utah school."},{"id":"per-1q188j8","q":"How many documents proving Utah residency must you bring when you apply for a license?","a":"Two","o":["Two","One","Three","Four"],"why":"Two acceptable residency documents are required."},{"id":"per-qbfarp","q":"Residency documents such as a bank statement or utility bill must be dated within:","a":"90 days","o":["90 days","30 days","6 months","One year"],"why":"Each residency proof must show your name and address and be dated within 90 days."},{"id":"per-fiv32c","q":"Which of these can be used as proof of where you live?","a":"A utility bill with your name and address","o":["A utility bill with your name and address","A library card with your name and picture","A gym membership card with your signature","A store receipt from last week's groceries"],"why":"Accepted proofs include utility bills, bank statements, rental contracts, and property tax notices."},{"id":"per-1jghe8e","q":"Which birth certificate will the Driver License Division accept?","a":"A certified copy from the state of birth","o":["A certified copy from the state of birth","A hospital souvenir certificate","A laminated copy","A photocopy"],"why":"Use a state-certified birth certificate. Hospital, laminated, or photocopied ones are not accepted."},{"id":"per-rq8vl9","q":"Your name changed after you got married. What do you need to get a license in the new name?","a":"A certified marriage certificate or other legal paperwork","o":["A certified marriage certificate or other legal paperwork","A short note from your employer about the change","A new credit card showing the new last name","A signed statement from a friend or relative"],"why":"A legal document such as a marriage certificate, divorce decree, or court order is needed for a name change."},{"id":"per-1wrz444","q":"You moved last week. Will the post office forward your Driver License Division mail?","a":"No, you must update your address with the division","o":["No, you must update your address with the division","Yes, forwarding updates it automatically","Yes, but only for 30 days","No, and you do not need to tell the division"],"why":"The post office does not forward division mail. Tell the division within 10 days."},{"id":"per-tp6fob","q":"Which endorsement lets a driver operate a school bus?","a":"S","o":["S","P","T","H"],"why":"S is the school bus endorsement. P is passenger, T is doubles or triples, and H is hazardous materials."},{"id":"per-1gpwvle","q":"A Commercial Driver License (CDL) is needed for a vehicle rated at what weight or more?","a":"26,001 pounds","o":["26,001 pounds","10,001 pounds","16,001 pounds","20,000 pounds"],"why":"A CDL is required at 26,001 pounds GVWR or more, or for buses, hazmat, and similar vehicles."},{"id":"per-1lrj2gq","q":"What can a Driving Privilege Card (DPC) be used for?","a":"Driving only, not as ID or to prove your age","o":["Driving only, not as ID or to prove your age","Driving and boarding a plane inside the country","Driving and buying age restricted items in stores","Driving and proving identity at a bank"],"why":"A DPC is for driving only and is not valid identification or age verification."},{"id":"per-f4aj9f","q":"Can a person hold a Utah driver license and a Utah ID card at the same time?","a":"No, only one at a time","o":["No, only one at a time","Yes, if the ID is for a different address","Yes, if the person is under 21","Yes, with a doctor's note"],"why":"A person may not hold a driver license and an ID card at the same time."},{"id":"per-8kig60","q":"A 20 year old completes an approved driver education course. What happens to the 90 day permit holding rule?","a":"It is waived","o":["It is waived","It is doubled","It still must be done in full","It becomes six months"],"why":"Finishing an approved course waives the 90 day permit requirement for adults 19 and older."}]},{"id":"tests","name":"Tests & Paperwork","icon":"📝","src":"Handbook: Examinations","qs":[{"id":"tes-1a6nw4g","q":"What score do you need to pass the Utah written knowledge test?","a":"80% or better","o":["80% or better","70% or better","75% or better","90% or better"],"why":"The written test passing score is 80% or better."},{"id":"tes-qp3yzd","q":"How long is a passing written test score valid for an entry-level permit?","a":"18 months","o":["18 months","6 months","12 months","24 months"],"why":"A passing score stays valid 18 months for the entry-level permit."},{"id":"tes-14zfckv","q":"How is the written knowledge test timed?","a":"It is untimed","o":["It is untimed","30 minutes total","60 minutes total","15 minutes total"],"why":"The test is untimed. Most people take 30 to 45 minutes."},{"id":"tes-azm09c","q":"The written test fee covers how many attempts within 12 months?","a":"Up to three","o":["Up to three","Just one","Up to two","Unlimited"],"why":"The fee covers up to three attempts in 12 months. Three more need another fee."},{"id":"tes-q8t8j9","q":"What score is required on the online Traffic Safety and Trends Exam?","a":"100%","o":["100%","80%","70%","90%"],"why":"First-time Class D applicants must score 100%, and they may retake it as needed."},{"id":"tes-11m2n0z","q":"Who may be in the car during the driving skills test?","a":"Only you and the examiner","o":["Only you and the examiner","You, the examiner, and a parent","You and a friend","You, the examiner, and your instructor"],"why":"Only the applicant and the examiner ride along."},{"id":"tes-1q9dkzu","q":"Who provides the vehicle for the driving skills test?","a":"The applicant","o":["The applicant","The testing office","The examiner","A rental service"],"why":"You bring a registered, clean, safe vehicle."},{"id":"tes-un4z63","q":"Which of these is NOT required on a skills test vehicle?","a":"A front license plate","o":["A front license plate","A working horn","Working brake lights","Working safety belts"],"why":"The front plate is not required after January 1, 2025. The rest still are."},{"id":"tes-1fys8az","q":"Which of these will automatically fail a skills test?","a":"Failing to yield to a pedestrian","o":["Failing to yield to a pedestrian","Asking the examiner to repeat a direction","Checking mirrors before a lane change","Adjusting your seat before you start"],"why":"Failing to yield to others is an automatic fail, along with speeding, rolling stops, and avoidable crashes."},{"id":"tes-1e1vbvh","q":"What must you bring to the skills test besides your permit?","a":"Valid registration and insurance for the vehicle","o":["Valid registration and insurance for the vehicle","Your school transcript and test receipt","A copy of your birth certificate again","A written note from your parent"],"why":"Bring your permit, valid registration, and valid insurance."},{"id":"tes-10iew1c","q":"How many driving skills tests can you take in one day?","a":"One","o":["One","Two","Three","As many as you need"],"why":"Only one skills test per day is allowed."},{"id":"tes-1mgl3he","q":"Tests must be completed within how long after paying the test fee?","a":"Six months","o":["Six months","Three months","One year","Eighteen months"],"why":"All tests must be finished within six months of paying."},{"id":"tes-1jny5ay","q":"Which of these must be working on a vehicle you bring to the driving skills test?","a":"The horn and the brake lights","o":["The horn and the brake lights","A backup camera","Cruise control","A navigation screen"],"why":"The checklist requires a working horn, brake lights, turn signals, safety belts, and a parking brake."},{"id":"tes-wuu8wz","q":"The Utah Class D vision standard requires acuity of at least:","a":"20/40 in at least one eye","o":["20/40 in at least one eye","20/20 in each of your eyes","20/30 in at least one eye","20/60 in at least one eye"],"why":"Class D needs 20/40 in at least one eye and a 90 degree visual field."},{"id":"tes-zk03n7","q":"What is the most written knowledge tests you can take in one day?","a":"Two, if the division can fit them in","o":["Two, if the division can fit them in","One","Three","As many as you can pay for"],"why":"The division gives up to two written tests per day when it can."},{"id":"tes-g3m5mo","q":"You failed the written test and need to come back. What must you do?","a":"Schedule a written retest appointment","o":["Schedule a written retest appointment","Walk in the next morning","Wait one full year","Take driver education again"],"why":"A failed attempt that needs a return trip requires a scheduled retest appointment."},{"id":"tes-19vm4tx","q":"You fail the written test three times. What happens next?","a":"You pay another fee for three more tries","o":["You pay another fee for three more tries","You wait one year to try again","You must retake driver education","You lose your permit forever"],"why":"The fee covers three tries in 12 months. After that, another fee buys three more."},{"id":"tes-1isx1sf","q":"Who must take the online Traffic Safety and Trends Exam?","a":"All first-time regular Class D applicants","o":["All first-time regular Class D applicants","Only drivers under 18","Only drivers who failed the skills test","Only drivers renewing after 8 years"],"why":"First-time Class D applicants must pass it, and they can retake it as often as needed."},{"id":"tes-19dn4mc","q":"About how much of the Traffic Safety and Trends Exam covers the main causes of traffic deaths?","a":"50 percent","o":["50 percent","10 percent","25 percent","90 percent"],"why":"Half of its questions are based on Utah Highway Safety Office data about leading causes of traffic deaths."},{"id":"tes-b9ghjy","q":"What is the minimum age to take the driving skills test at a Driver License Division office?","a":"16","o":["16","15","17","18"],"why":"The division tests at 16 and older. Third-party testers and high schools can test at 15."},{"id":"tes-1gmxvrg","q":"About how long does the driving skills test last?","a":"About 20 minutes","o":["About 20 minutes","About 5 minutes","About 45 minutes","About 90 minutes"],"why":"The test lasts about 20 minutes."},{"id":"tes-78ef5v","q":"Which mirror setup must a skills test vehicle have?","a":"Two rear view mirrors, one outside on the driver's left","o":["Two rear view mirrors, one outside on the driver's left","One inside mirror only","A backup camera and one inside mirror","Two outside mirrors and no inside mirror"],"why":"The checklist requires two rear view mirrors, with one on the outside to the driver's left."},{"id":"tes-12ps5gw","q":"Which of these is required on a skills test vehicle?","a":"A working emergency or parking brake","o":["A working emergency or parking brake","A navigation screen mounted on the dashboard","A cruise control system that works well","Tinted windows on the rear and side doors"],"why":"The test car needs a working emergency or parking brake, a horn, brake lights, and safety belts."},{"id":"tes-1qtfy6l","q":"What must be true about the tires on your skills test vehicle?","a":"They have no bald spots","o":["They have no bald spots","They are all brand new","They are all winter tires","They are the same brand"],"why":"The checklist says tires cannot have bald spots."},{"id":"tes-1eq40pd","q":"Your skills test vehicle has an unregistered plate. What will happen at the test?","a":"The test will not be given","o":["The test will not be given","The examiner will add points to your score","You can take the test but must pay a fine","The test will be given with a warning"],"why":"Skills tests are not given with unregistered or unsafe vehicles."},{"id":"tes-k4u62g","q":"You drive over a curb for no reason during the skills test. What is the result?","a":"An automatic failure","o":["An automatic failure","One minor point off","A warning only","Nothing, if you did not hit anyone"],"why":"Driving over sidewalks or curbs unnecessarily is an automatic failure."},{"id":"tes-719l0r","q":"Which of these is an automatic failure on the skills test?","a":"The examiner has to take control of the vehicle","o":["The examiner has to take control of the vehicle","You ask the examiner to repeat a direction","You check your mirrors twice","You adjust the heater"],"why":"If the examiner must take control, the test is failed."},{"id":"tes-zoib0i","q":"During the skills test, you roll through a stop sign without stopping. What happens?","a":"You automatically fail","o":["You automatically fail","You lose a few points","You get a warning","Nothing, if no one was near"],"why":"Rolling through stops is an automatic failure."},{"id":"tes-1spil86","q":"Which of these is scored on the driving skills test?","a":"Parallel parking and parking on a hill","o":["Parallel parking and parking on a hill","How fast you finish the route","The type of car you drive","How loud your radio is"],"why":"The test scores turns, starting and stopping, backing, and parking on hills, between cars, and parallel."},{"id":"tes-1nv3txd","q":"Your learner permit expires before you finish all your testing. What may happen?","a":"You may have to take additional tests","o":["You may have to take additional tests","Nothing changes","You pass the skills test automatically","You must wait 5 years"],"why":"Expired permits or expired earlier tests may mean more testing."},{"id":"tes-hishpd","q":"Which steering styles are accepted during the skills test?","a":"Hand-over-hand or push-pull, hands on the outside","o":["Hand-over-hand or push-pull, hands on the outside","Only hand-over-hand, with one hand inside the rim","One hand on top of the wheel the whole time","Both hands on the inside spokes of the wheel"],"why":"Both hand-over-hand and push-pull are fine if your hands stay on the outside of the wheel."},{"id":"tes-129j09i","q":"You booked a renewal appointment but really need a skills test. What can happen?","a":"Your appointment may be voided","o":["Your appointment may be voided","The clerk gives the skills test anyway","Nothing, since all appointments are the same","You get a free retest"],"why":"Booking the wrong service can void your appointment, so book the right one."},{"id":"tes-17p090b","q":"Which documents does the Driver License Division accept?","a":"Originals or certified copies from the issuing agency","o":["Originals or certified copies from the issuing agency","Photocopies of your birth certificate and papers","Faxes sent by the agency that issued them","Phone pictures of your documents on your screen"],"why":"Faxes and photocopies are not accepted."},{"id":"tes-189u2ro","q":"Which testing service gives driving skills tests besides the Driver License Division?","a":"Third-party testers","o":["Third-party testers","Insurance agencies","Auto repair shops","Car dealers"],"why":"Third-party testers and some high schools give skills tests and may charge their own fee."}]},{"id":"ready","name":"Get Ready to Drive","icon":"💺","src":"Handbook: Preparing Your Vehicle","qs":[{"id":"rea-hhwgzq","q":"Who in the car must wear a fastened safety belt or ride in a child seat?","a":"Everyone in the vehicle","o":["Everyone in the vehicle","Only the driver","The driver and front passenger","Anyone under 16"],"why":"Utah requires everyone to be belted or in a child seat."},{"id":"rea-1alby34","q":"How much space should you leave between your chest and the steering wheel?","a":"About 10 inches","o":["About 10 inches","About 4 inches","About 6 inches","About 15 inches"],"why":"Leave 10 inches so the air bag can inflate safely."},{"id":"rea-6291m3","q":"Where should the lap belt sit?","a":"Across your hips, not your stomach","o":["Across your hips, not your stomach","Across your stomach and ribs","Across your lower chest","Across your stomach, above the hips"],"why":"A lap belt crosses the hips. A belt on the stomach can injure organs."},{"id":"rea-1te3bqx","q":"Where should the shoulder belt cross your body?","a":"Over your shoulder and chest","o":["Over your shoulder and chest","Under your arm and across the ribs","Behind your back and across the lap","Across your neck and upper chest"],"why":"Never wear it under the arm or behind the back."},{"id":"rea-pk6rjv","q":"Children age 8 and under need an approved child seat unless they are how tall?","a":"57 inches","o":["57 inches","48 inches","52 inches","60 inches"],"why":"Children age 8 and under need a seat until they are 57 inches tall."},{"id":"rea-14g6jds","q":"How long should a child ride rear-facing, if the seat allows?","a":"Until at least age 2 and 30 pounds","o":["Until at least age 2 and 30 pounds","Until at least age 1 and 20 pounds","Until at least age 3 and 40 pounds","Until 6 months"],"why":"The handbook says rear-facing until at least age two and 30 pounds."},{"id":"rea-1h1p9tj","q":"A forward-facing child seat with a harness is used until at least:","a":"Age 4 and 40 pounds","o":["Age 4 and 40 pounds","Age 2 and 25 pounds","Age 6 and 60 pounds","Age 3 and 30 pounds"],"why":"After rear-facing, use a harness seat until at least age four and 40 pounds."},{"id":"rea-o0wwa9","q":"Where should children 12 and under ride?","a":"Buckled in a rear seat","o":["Buckled in a rear seat","In the front with a belt","In the front if they are tall","On an adult's lap"],"why":"Children 12 and under belong in the back seat."},{"id":"rea-h1fpgc","q":"Which is never safe for an infant?","a":"Riding in front of a passenger-side air bag","o":["Riding in front of a passenger-side air bag","Riding in an approved rear-facing seat","Riding in the middle of the back seat","Riding buckled in a rear passenger seat"],"why":"Infants should never ride in front of a passenger-side air bag."},{"id":"rea-13ezibj","q":"Where should the head restraint touch your head?","a":"The back of your head, above ear level","o":["The back of your head, above ear level","The base of your neck only","The middle of your upper back","Just below your ear level"],"why":"Set it so it contacts the back of the head above ear level."},{"id":"rea-14ks7ba","q":"How should you set your outside mirrors?","a":"To cut blind spots and show adjacent lanes","o":["To cut blind spots and show adjacent lanes","To show the side of your own car","To show only the road behind you","To point down toward the pavement"],"why":"Set them wide to minimize blind spots."},{"id":"rea-e2itau","q":"Smoking in a car with a passenger 15 or younger is:","a":"An infraction","o":["An infraction","Fine with a window open","Fine if a parent is driving","A felony"],"why":"Smoking while transporting a child 15 or younger is an infraction in Utah."},{"id":"rea-l80hpt","q":"Which type of vehicle is exempt from the belt law?","a":"A school bus","o":["A school bus","A pickup truck","A minivan","A taxi"],"why":"Exempt vehicles include school buses, motorcycles, mopeds, authorized emergency vehicles, and vehicles built without belts."},{"id":"rea-1vimshu","q":"A 7 year old is 50 inches tall. What does Utah require?","a":"An approved child seat or booster seat","o":["An approved child seat or booster seat","A lap belt only","The front seat with a shoulder belt","Nothing, belts are enough at 7"],"why":"Children 8 and under need a car or booster seat unless they are 57 inches tall."},{"id":"rea-sy6lap","q":"A child who is 8 or younger is already 57 inches tall. What may the child use?","a":"A regular safety belt","o":["A regular safety belt","Nothing, belts are not needed","The front seat with no restraint","A lap belt behind the back"],"why":"The child seat rule ends at 57 inches. Everyone still needs a belt."},{"id":"rea-1xkdq3q","q":"A booster seat is used from about age 4 and 40 pounds until:","a":"The belt fits correctly and the child is 57 inches tall","o":["The belt fits correctly and the child is 57 inches tall","The child turns six years old and weighs 50 pounds","The child can sit still for a full car trip","The child reaches 4 feet 2 inches and 60 pounds"],"why":"Use a booster until the adult belt fits properly and the child reaches 57 inches."},{"id":"rea-faf1z7","q":"How much force does a 150 pound person create in a crash at 30 mph?","a":"About 4,500 pounds","o":["About 4,500 pounds","About 450 pounds","About 1,500 pounds","About 9,000 pounds"],"why":"Crash force is body weight times speed. 150 times 30 is 4,500."},{"id":"rea-1g89qhd","q":"Being thrown from a car in a crash makes your chance of being killed how many times greater?","a":"23 times","o":["23 times","3 times","10 times","50 times"],"why":"The handbook says ejection makes death 23 times more likely."},{"id":"rea-9z4wf","q":"About 70 percent of crashes happen at speeds under:","a":"40 mph","o":["40 mph","20 mph","55 mph","65 mph"],"why":"Most crashes happen at speeds under 40 mph, so belts matter even on short trips."},{"id":"rea-cpr9mp","q":"How close to home do three of four fatal crashes happen?","a":"Within 25 miles","o":["Within 25 miles","Within 2 miles","Within 100 miles","Over 200 miles away"],"why":"Three of four fatal crashes happen within 25 miles of home."},{"id":"rea-1ve0c0q","q":"How can a safety belt ticket be waived in Utah?","a":"By completing an online 30 minute safety belt course","o":["By completing an online 30 minute safety belt course","By paying double the fine","By writing an apology letter","By driving without a ticket for a week"],"why":"The fine may be waived by finishing the online safety belt course."},{"id":"rea-1e4ubew","q":"A 17 year old passenger is not wearing a belt. When can that passenger be cited?","a":"When the car is stopped for another reason","o":["When the car is stopped for another reason","Never, belts are only required under 16","Only on freeways","Only at night"],"why":"Passengers 16 and older can be cited for a belt violation if the car is stopped for something else."},{"id":"rea-gro0vv","q":"Air bags can inflate at up to how fast?","a":"200 mph","o":["200 mph","50 mph","100 mph","400 mph"],"why":"Air bags can open at up to 200 mph, so sit back from the wheel and wear your belt."},{"id":"rea-50csei","q":"Taking apart or changing an air bag system so it will not work is:","a":"A Class B misdemeanor","o":["A Class B misdemeanor","A parking ticket","Allowed for repairs","A Class C infraction only"],"why":"Disabling or modifying an air bag system is a Class B misdemeanor."},{"id":"rea-1dtf3xf","q":"Where should the top of the steering wheel be?","a":"Below your chin and no higher than your shoulders","o":["Below your chin and no higher than your shoulders","At eye level so you can see over the dash","Above your head restraint to reach the wheel","Level with your forehead and fully extended"],"why":"Keep the wheel top at or below shoulder level, under your chin."},{"id":"rea-10hxlz1","q":"To set your left outside mirror, rest your head against the left window. What should you barely see?","a":"The rear left edge of your own car","o":["The rear left edge of your own car","Nothing of your car at all","The whole left side of your car","Only the car behind you"],"why":"Set it so you just see the back edge of your car, which cuts the blind spot."},{"id":"rea-hu70qr","q":"To set your right outside mirror, lean right until your head is under the inside mirror. What should you barely see?","a":"The right side of your own car","o":["The right side of your own car","Nothing of your car at all","The back bumper only","The full right door"],"why":"Set it so you barely see your car's right side."},{"id":"rea-pvi49k","q":"Your inside mirror should be set so it:","a":"Frames the rear window","o":["Frames the rear window","Shows only the back seat","Points at the road behind the trunk","Shows only the left lane"],"why":"The inside mirror should frame your rear window."},{"id":"rea-1kgumiv","q":"How should your foot move between the gas and brake?","a":"Easily, with your heel resting on the floor","o":["Easily, with your heel resting on the floor","With your whole leg lifted","With your toe off the pedal","With your foot braced against the seat"],"why":"Keep your heel on the floor and pivot between the pedals."},{"id":"rea-31qlj8","q":"Which child car seat is acceptable?","a":"One that is crash tested and meets federal standards","o":["One that is crash tested and meets federal standards","One bought used with the label worn off","One made at home from a safety kit","Any seat as long as the child is buckled in"],"why":"Seats must be crash tested and meet Federal Motor Vehicle Safety Standards."},{"id":"rea-1h4u21o","q":"How can drivers and front passengers lower their air bag risk?","a":"Sit as far back as is practical","o":["Sit as far back as is practical","Lean forward over the wheel","Turn the air bag off by hand","Recline the seat"],"why":"Sit as far back as practical and always wear the lap and shoulder belt."},{"id":"rea-vv3ndb","q":"A child must ride in the front seat. What should you do?","a":"Move the seat as far back as possible and use the right car seat","o":["Move the seat as far back as possible and use the right car seat","Put the child on an adult's lap for protection","Slide the seat forward so the child can see out","Use only a lap belt and recline the seat back"],"why":"If the front is the only choice, slide the seat back and secure the child in the right seat."},{"id":"rea-3mjqok","q":"Is a safety belt likely to trap you in a fire or in water?","a":"No, fire or water is in under 1 percent of injury crashes","o":["No, fire or water is in under 1 percent of injury crashes","Yes, belts jam in about half of all crashes","Yes, most crashes end with a fire or in water","Yes, belts trap people in about one crash in ten"],"why":"Less than half of one percent of injury crashes involve fire or submersion."},{"id":"rea-pprkhy","q":"In Utah, about two of three motor vehicle deaths would not have happened if:","a":"Everyone had worn a safety belt","o":["Everyone had worn a safety belt","Cars were smaller","Speed limits were raised","Every driver had air bags"],"why":"About two of three deaths could be prevented by belts."},{"id":"rea-15we3rj","q":"Which of these must a driver check before moving the car?","a":"Lights and gauges, like fuel, ABS, and air bag lights","o":["Lights and gauges, like fuel, ABS, and air bag lights","Only the radio and the cabin temperature","Only the tire brand and the paint color","Only the clock and the air freshener"],"why":"Check lights and gauges after turning on the ignition, before you shift and go."},{"id":"rea-skite1","q":"When starting an automatic car, it must first be in:","a":"Park","o":["Park","Reverse","Drive","Low gear"],"why":"Start the engine in Park, or with the clutch pushed in on a manual."}]},{"id":"basic","name":"Basic Driving","icon":"🛞","src":"Handbook: Basic Driving","qs":[{"id":"bas-114bjt","q":"Where must you never back up?","a":"On a freeway or interstate","o":["On a freeway or interstate","In a private driveway","In a shopping center lot","On a quiet residential street"],"why":"The handbook says never back on a freeway or interstate."},{"id":"bas-1214bia","q":"When backing, how should you check behind you?","a":"Look through the rear window","o":["Look through the rear window","Use only the side mirrors","Use only the dashboard camera","Watch only the curb"],"why":"Mirrors do not show the area right behind the car."},{"id":"bas-wengrw","q":"When backing, which way should you steer?","a":"The way you want the back of the car to go","o":["The way you want the back of the car to go","The opposite way you want the back to go","Toward the curb at all times","Always to the left side first"],"why":"Steer in the direction you want the rear to move."},{"id":"bas-62v5q2","q":"How long should you signal before a lane change?","a":"At least two seconds","o":["At least two seconds","About one second","Only when a car is nearby","Until the lane change is half done"],"why":"Signal at least two seconds before moving, then head check."},{"id":"bas-o629up","q":"Before changing lanes you should always:","a":"Check mirrors and do a head check","o":["Check mirrors and do a head check","Tap your horn to alert drivers","Brake lightly to slow traffic","Flash your high beams twice"],"why":"Check mirrors, signal, and look over your shoulder."},{"id":"bas-hb0cav","q":"Changing lanes in the middle of an intersection is:","a":"Not allowed","o":["Not allowed","Fine if the lane is clear","Fine on a green light","Fine at night"],"why":"Do not change lanes in an intersection."},{"id":"bas-1e5ea02","q":"On a multi-lane road, which lane should you normally use?","a":"The far right lane, unless passing or blocked","o":["The far right lane, unless passing or blocked","The far left lane, to keep up","Whichever lane seems the fastest","The center lane, to avoid merging cars"],"why":"Stay right unless you are passing or the lane is blocked."},{"id":"bas-se6kw1","q":"At a zipper merge, you should:","a":"Use both lanes, then alternate at the merge point","o":["Use both lanes, then alternate at the merge point","Merge into one lane as early as you can","Speed up to get ahead of the other lane","Stop at the merge and wait for a gap"],"why":"With a zipper merge, drivers alternate at the merge point."},{"id":"bas-4la8wi","q":"When you park at a curb, how close should your wheels be?","a":"Within 12 inches","o":["Within 12 inches","Within 24 inches","Within 6 inches","Within 18 inches"],"why":"Park as close as possible, within 12 inches of the curb."},{"id":"bas-1mo4ubm","q":"How close to a fire hydrant may you park?","a":"No closer than 15 feet","o":["No closer than 15 feet","No closer than 5 feet","No closer than 10 feet","No closer than 25 feet"],"why":"Keep 15 feet clear of a hydrant."},{"id":"bas-1z12e0b","q":"How close to a crosswalk may you park?","a":"No closer than 20 feet","o":["No closer than 20 feet","No closer than 10 feet","No closer than 15 feet","No closer than 5 feet"],"why":"Stay at least 20 feet back from a crosswalk."},{"id":"bas-1vifrti","q":"How close to the rail at a railroad crossing may you park?","a":"No closer than 50 feet","o":["No closer than 50 feet","No closer than 25 feet","No closer than 15 feet","No closer than 100 feet"],"why":"Do not park within 50 feet of a crossing unless signs allow it."},{"id":"bas-ppz40l","q":"When parking downhill next to a curb, turn your wheels:","a":"Toward the curb","o":["Toward the curb","Away from the curb","Straight ahead","Toward the road"],"why":"Downhill, wheels turn toward the curb so the car rolls into it."},{"id":"bas-avlzg4","q":"When parking uphill next to a curb, turn your wheels:","a":"Away from the curb","o":["Away from the curb","Toward the curb","Straight ahead","It does not matter"],"why":"Uphill, wheels turn away from the curb."},{"id":"bas-1rxnv64","q":"After passing, you may return to the right lane no less than how far from an oncoming vehicle?","a":"200 feet","o":["200 feet","50 feet","100 feet","500 feet"],"why":"Return to the right lane at least 200 feet ahead of oncoming traffic."},{"id":"bas-k6ie46","q":"Which of these is a place where you must not pass?","a":"Before a railroad crossing or bridge","o":["Before a railroad crossing or bridge","On a straight road with a clear view","In the left lane of a multi-lane road","On a road with a broken yellow line on your side"],"why":"Never pass before a railroad crossing or bridge, at intersections, or where view is blocked."},{"id":"bas-dg8oos","q":"Where should your hands be on the steering wheel?","a":"On the outside of the wheel","o":["On the outside of the wheel","At the very top of the wheel","One hand on the inside spokes","Anywhere that feels comfortable"],"why":"Keep both hands on the outside of the wheel."},{"id":"bas-aebhe3","q":"What following distance does the handbook give for normal conditions?","a":"At least two seconds","o":["At least two seconds","One second","Four car lengths exactly","Ten seconds"],"why":"Use a two-second gap, and more in bad weather."},{"id":"bas-99zrks","q":"When stopped behind another car, you should be able to see:","a":"The bottom of its rear tires","o":["The bottom of its rear tires","Only its rear bumper","Only its license plate","Only the top of its trunk"],"why":"Seeing its rear tires leaves room to pull around."},{"id":"bas-1y36fzr","q":"Where is a U-turn never allowed?","a":"On a freeway","o":["On a freeway","On a wide quiet street with no sign","At a signal with no sign forbidding it","From the left lane of a wide street"],"why":"U-turns are illegal on a freeway, on railroad tracks, and where signs forbid them."},{"id":"bas-1u4v2io","q":"Before you pull out of a parking space, what is the right order?","a":"Shift, check traffic and head, signal, then speed up smoothly","o":["Shift, check traffic and head, signal, then speed up smoothly","Signal, speed up quickly, then check traffic behind","Speed up, shift gears, then do a quick mirror check","Check your radio, signal, then shift and pull out"],"why":"Shift into gear, do a traffic check and head check, signal if needed, then speed up smoothly."},{"id":"bas-cwazil","q":"Why should you walk around your car before backing out?","a":"Small kids and objects can hide behind your car","o":["Small kids and objects can hide behind your car","It warms up your tires before you drive","Your mirrors show every spot behind the car","State law requires a walk around every day"],"why":"Small kids and objects can hide in the area right behind the car."},{"id":"bas-1vcvjtu","q":"When you back up, what should your hands do?","a":"Left hand on the wheel, right arm over the seat back","o":["Left hand on the wheel, right arm over the seat back","Both hands at the very top of the wheel","Right hand on the wheel, left arm out the window","Both hands off the wheel while you look back"],"why":"Hold the wheel with your left hand, turn, and look through the rear window."},{"id":"bas-cx371w","q":"How should you back up?","a":"Slowly, while looking to the rear until you stop","o":["Slowly, while looking to the rear until you stop","Quickly, to clear the lane as soon as you can","Using only your side mirrors and the radio","Using only the backup camera and no head turn"],"why":"Back slowly and keep looking to the rear until you have stopped."},{"id":"bas-wpo2ay","q":"You finish a left turn on a road with two lanes going each way. Which lane do you turn into?","a":"The left lane, right of the centerline","o":["The left lane, right of the centerline","The right lane, as far from the center as possible","The center turn lane, until traffic has cleared","Whichever lane has the fewest cars in it"],"why":"Finish a left turn in the lane just to the right of the centerline."},{"id":"bas-1rcoeag","q":"You finish a right turn on a multi-lane road. Which lane do you turn into?","a":"The right-most lane","o":["The right-most lane","The left lane","The center turn lane","Whichever lane is empty"],"why":"Finish a right turn in the right-most lane."},{"id":"bas-11ewnnd","q":"You merge into a lane where some cars are close behind you. Who must yield?","a":"The merging driver yields to cars that are a threat","o":["The merging driver yields to cars that are a threat","The cars already in the lane yield to you","Whichever driver has the bigger vehicle goes first","Neither driver, since lanes merge first come first"],"why":"Merging drivers yield to continuing traffic that is close enough to be a threat."},{"id":"bas-bavayo","q":"Not using the zipper merge where it is required is:","a":"An infraction","o":["An infraction","A felony","Not a violation","A Class A misdemeanor"],"why":"Violating the zipper merge rule is an infraction."},{"id":"bas-x6ko26","q":"Where should you stop at a stop sign that has a stop line?","a":"Behind the stop line","o":["Behind the stop line","On top of the crosswalk","In the middle of the intersection","Past the line so you can see better"],"why":"Stop behind the stop line or crosswalk, not on top of it."},{"id":"bas-t64x9l","q":"You must stop before the sidewalk when you drive out of:","a":"An alley, a private driveway, or a building","o":["An alley, a private driveway, or a building","A freeway off-ramp onto a city street","A one-way street into a two-way street","A roundabout onto the next road"],"why":"Stop before the sidewalk or street when entering from an alley, driveway, private road, or building."},{"id":"bas-1jem4uq","q":"You are in a crash. When may you leave the scene?","a":"After the legal requirements have been met","o":["After the legal requirements have been met","Right away, if no one seems to be hurt","After about five minutes of waiting nearby","As soon as the other driver drives away"],"why":"You must stay until you have given your information and helped anyone hurt."},{"id":"bas-1g68d3b","q":"How close to a stop sign may you park?","a":"No closer than 30 feet","o":["No closer than 30 feet","No closer than 10 feet","No closer than 5 feet","No closer than 50 feet"],"why":"Do not park within 30 feet of a stop sign, yield sign, flashing beacon, or traffic signal."},{"id":"bas-1pj7zkh","q":"How close to a fire station driveway may you park?","a":"No closer than 20 feet","o":["No closer than 20 feet","No closer than 10 feet","No closer than 30 feet","No closer than 5 feet"],"why":"Keep 20 feet clear of a fire station entrance."},{"id":"bas-13zfnab","q":"Which of these is a legal place to park?","a":"In a marked stall in a parking lot","o":["In a marked stall in a parking lot","Beside a red painted curb","In front of a driveway","Double parked next to a car"],"why":"Marked stalls are legal. Red curbs, driveways, and double parking are not."},{"id":"bas-1ue41mo","q":"Where may you park on an interstate shoulder?","a":"Only if your vehicle breaks down or you are in distress","o":["Only if your vehicle breaks down or you are in distress","Anywhere that is wide enough to fit your car","Only at night when the shoulder is quiet","Only for under an hour with your flashers on"],"why":"Do not park on an interstate shoulder except for a breakdown or distress."},{"id":"bas-pm0uuv","q":"Where is parking never allowed?","a":"On a bridge or in a tunnel","o":["On a bridge or in a tunnel","In a marked stall","Beside an unpainted curb with no signs","In a driveway you own"],"why":"You may not park on a bridge, elevated highway, or in a tunnel."},{"id":"bas-1wv4xl8","q":"What should you do before you leave your parked car?","a":"Set the parking brake, turn off the engine, and lock the doors","o":["Set the parking brake, turn off the engine, and lock the doors","Leave the engine running so the heater stays on","Leave the keys in the ignition for a quick return","Roll down the windows so the car does not overheat"],"why":"Secure the car before you walk away."},{"id":"bas-19euvwk","q":"You park uphill where there is no curb. Which way should you turn your front wheels?","a":"To the right","o":["To the right","To the left","Straight ahead","Toward the road center"],"why":"With no curb, turn the wheels to the right so the car rolls off the road, not into the lane."},{"id":"bas-7tpokf","q":"When you parallel park, where do you first stop?","a":"Parallel to the car you will park behind","o":["Parallel to the car you will park behind","Two lanes over from the car","At the end of the block","Behind the next car in line"],"why":"Pull up even with the car in front of the space, then back in."},{"id":"bas-1mnlxp4","q":"On a multi-lane road, the left lane is mainly for:","a":"Passing slower vehicles","o":["Passing slower vehicles","Driving slowly to save fuel","Parking for short stops","Trucks and large vehicles only"],"why":"Use the left lane to pass, then move back right."},{"id":"bas-1v2lkp5","q":"Passing another car by driving on the shoulder is:","a":"Never allowed","o":["Never allowed","Allowed on freeways","Allowed at night","Allowed if the car ahead is slow"],"why":"Never pass on the shoulder or by leaving the road."},{"id":"bas-n3ovi1","q":"Someone is passing you. What should you do?","a":"Stay in your lane and keep a steady speed","o":["Stay in your lane and keep a steady speed","Speed up","Move toward the edge of the road","Brake hard"],"why":"Do not speed up. Hold your lane and speed so the other driver can finish the pass."},{"id":"bas-1g9ky1o","q":"When may you return to the lane after passing a car?","a":"Once you can see the passed car in your rearview mirror","o":["Once you can see the passed car in your rearview mirror","As soon as your front bumper clears the car","When you are next to its door","Right away"],"why":"Wait until the passed vehicle shows in your mirror, and be at least 200 feet ahead of oncoming traffic."},{"id":"bas-1iu9azl","q":"When is it illegal to pass?","a":"When a hill or curve blocks your view","o":["When a hill or curve blocks your view","When the road ahead is straight and clear","In a marked passing zone with no cars coming","When you are in the left lane on a multi-lane road"],"why":"Never pass where a hill or curve blocks your view."},{"id":"bas-q3fkh2","q":"A car is stopped at a crosswalk. Passing it is:","a":"Never allowed","o":["Never allowed","Allowed if you go slowly","Allowed if you honk","Allowed if no one is crossing now"],"why":"The stopped car may be letting a pedestrian cross, so never pass it."},{"id":"bas-qg9uwo","q":"A snowplow has flashing yellow lights and its blade down. You may not pass on:","a":"The side where the blade is deployed","o":["The side where the blade is deployed","The side away from the blade, at any time","Either side, whenever it is moving slowly","Neither side, even when the blade is up"],"why":"Do not pass on the side where the plow blade is down. With three or more plows in a row, pass on neither side."},{"id":"bas-sbi0wp","q":"You are about to pull away from the curb. Should you signal?","a":"Yes, signal whenever you pull to or from a curb","o":["Yes, signal whenever you pull to or from a curb","No, signals are only needed for turns at corners","Only at night or when it is raining outside","Only when other cars are close by"],"why":"Signal when pulling to or from a curb."},{"id":"bas-1wmamhy","q":"When should you use emergency flashers?","a":"When your vehicle is disabled on the highway","o":["When your vehicle is disabled on the highway","When it rains","When you are in a hurry","When you want to park for a minute anywhere"],"why":"Flashers warn others that your car is stopped or broken down."},{"id":"bas-1rxf1sb","q":"How should you grip the steering wheel?","a":"Firmly but gently with your fingers, not your palms","o":["Firmly but gently with your fingers, not your palms","Tightly with your palms","With one hand on the inside of the rim","With your thumbs hooked through the spokes"],"why":"Use your fingers and keep your thumbs up along the wheel face."},{"id":"bas-1kgidug","q":"Which kind of steering is best for parking, sharp right turns, and fixing a skid?","a":"Hand-over-hand","o":["Hand-over-hand","Pull-push","One-hand steering","Palm spinning"],"why":"Use hand-over-hand for critical steering. Pull-push is smoother for turning."},{"id":"bas-um8its","q":"What is a mistake to avoid in a right turn?","a":"Swinging wide or cutting the corner","o":["Swinging wide or cutting the corner","Using your turn signal for two full seconds","Doing a head check over your right shoulder","Slowing down before you start the turn"],"why":"Do not cut the corner or swing wide. Do a right head check."},{"id":"bas-gf4hb1","q":"You are turning on a road with multiple turn lanes. What should you do?","a":"Stay in your lane until the turn is complete","o":["Stay in your lane until the turn is complete","Change lanes in the middle of the turn","Drive over the island","Cut across into the next lane"],"why":"Pick the right lane before the turn and stay in it."},{"id":"bas-1g272aa","q":"You may drive over, across, or within an island:","a":"Never","o":["Never","When no cars are near","When you are turning left","When it is raining"],"why":"Do not drive over, across, or within any part of an island."},{"id":"bas-e26u3v","q":"When is a three-point turn the right choice?","a":"On a two-lane road that is too narrow for a U-turn","o":["On a two-lane road that is too narrow for a U-turn","On a busy four-lane road with no median","On a freeway when you miss your exit","Anywhere you miss a turn and want to go back"],"why":"Use it only on a two-lane road too narrow for a U-turn. Going around the block is better."},{"id":"bas-c7crf2","q":"Where is a U-turn not allowed?","a":"On a curve where you cannot see 500 feet each way","o":["On a curve where you cannot see 500 feet each way","On a quiet wide street with no signs posted","In your own driveway with a clear view","In an empty parking lot during the day"],"why":"Never U-turn where you cannot see traffic for 500 feet in both directions."},{"id":"bas-i9j2oa","q":"From where should you start a legal U-turn?","a":"From the left lane or just right of the center line","o":["From the left lane or just right of the center line","From the right curb or the right shoulder","From the middle of the nearest crosswalk","From any lane that has the least traffic"],"why":"Start from the left-hand lane or just right of center, with a signal and a head check."},{"id":"bas-hjhm4l","q":"Where should you look for hazards at intersections?","a":"Left and right at driveways, store entrances, and tracks","o":["Left and right at driveways, store entrances, and tracks","Straight ahead only, since that is where you go","At your speedometer to keep a safe speed","In your rearview mirror for drivers behind you"],"why":"Scan left and right in busy places and where people may step out."},{"id":"bas-1hhjqkc","q":"What is a blind spot?","a":"An area around your car that you cannot see in your mirrors","o":["An area around your car that you cannot see in your mirrors","The dark area under the dashboard of your car","The area just in front of your hood","A stretch of road with no street lights"],"why":"Blind spots are areas your mirrors do not show."},{"id":"bas-x8o58l","q":"What is a head check?","a":"Turning your head to look over your shoulder","o":["Turning your head to look over your shoulder","A quick glance at the rearview mirror","Checking the gauges on the dashboard","Looking at the car directly in front of you"],"why":"A head check means looking over your shoulder to see your blind spot."},{"id":"bas-3snktk","q":"After you finish a turn or lane change you should:","a":"Cancel your signal","o":["Cancel your signal","Leave your signal on for a block","Flash your high beams","Honk twice"],"why":"Cancel the signal once the move is complete."},{"id":"bas-105y98t","q":"Right before you turn left, you should do a head check over which shoulder?","a":"Left shoulder","o":["Left shoulder","Right shoulder","Neither","Both at the same time"],"why":"For a left turn, do a head check over your left shoulder."},{"id":"bas-fegbxh","q":"When you stop behind a crosswalk or stop line, you should:","a":"Stop behind it, not on top of it","o":["Stop behind it, not on top of it","Stop on the line","Stop past it to see better","Stop far back"],"why":"Stay behind the line so pedestrians have room."}]},{"id":"signs","name":"Road Signs","icon":"🛑","src":"Handbook: Signs","qs":[{"id":"sig-tlcf1r","q":"What does this sign mean?","a":"Come to a full stop, then go when it is safe","o":["Come to a full stop, then go when it is safe","Slow down and go if no one is coming","Stop only if other cars are present","Stop and wait for the flagger to wave"],"why":"A STOP sign always means a complete stop, then yield where required.","vis":"stop"},{"id":"sig-9h8sk0","q":"What should you do at this sign?","a":"Slow down and let other traffic go first","o":["Slow down and let other traffic go first","Come to a full stop every single time","Speed up to merge ahead of other traffic","Stop only if a pedestrian is crossing"],"why":"A YIELD sign means slow down and let traffic with the right-of-way go first.","vis":"yield"},{"id":"sig-1lfqs59","q":"This sign tells you:","a":"The maximum legal speed is 25 mph","o":["The maximum legal speed is 25 mph","The minimum legal speed is 25 mph","The suggested speed is 25 mph","The speed limit changes in 25 miles"],"why":"A speed limit sign shows the highest legal speed in good conditions.","vis":"speed25"},{"id":"sig-q9x6d8","q":"This round yellow sign means:","a":"A railroad crossing is ahead; slow and look","o":["A railroad crossing is ahead; slow and look","A rail passenger station is ahead","A roundabout is coming up ahead","A truck crossing is coming up ahead"],"why":"The round yellow RR sign warns that a crossing is ahead. Be ready to stop.","vis":"rr"},{"id":"sig-vchlo","q":"This white X sign at a crossing means:","a":"A railroad crossing; yield to any train","o":["A railroad crossing; yield to any train","Road closed to all traffic ahead","A railroad museum is just ahead","No parking within 50 feet of the tracks"],"why":"A crossbuck marks a railroad crossing. Yield to trains.","vis":"crossbuck"},{"id":"sig-1ux0q30","q":"This five-sided sign means:","a":"A school zone or school crossing is near","o":["A school zone or school crossing is near","A playground with no school nearby","A school bus stop is just ahead","A hospital zone with quiet hours"],"why":"A pentagon sign warns of a school zone or crossing.","vis":"school"},{"id":"sig-9nhvc3","q":"This sign means:","a":"Do not enter","o":["Do not enter","No parking","One way street","Road closed for the season"],"why":"A red circle with a white bar means you may not enter. You would be going the wrong way.","vis":"dne"},{"id":"sig-t2arsh","q":"You see this sign. What does it tell you?","a":"You are driving against traffic","o":["You are driving against traffic","You are in the wrong lane to turn","You are in a no-passing zone","A detour is ahead"],"why":"WRONG WAY warns you are heading the wrong direction. Stop and turn around safely.","vis":"wrongway"},{"id":"sig-w0next","q":"This sign means:","a":"Traffic moves only the way the arrow points","o":["Traffic moves only the way the arrow points","Two-way traffic is coming up ahead","The detour route leads this way","Only right turns are allowed here"],"why":"ONE WAY means traffic flows only the way the arrow points. Never drive against it.","vis":"oneway"},{"id":"sig-xlxfgz","q":"This sign means:","a":"U-turns are not allowed","o":["U-turns are not allowed","Left turns are not allowed","The road ends ahead","You must turn around"],"why":"A red circle with a slash cancels the picture inside it. This sign bans U-turns.","vis":"nouturn"},{"id":"sig-1s0b41t","q":"Orange signs like this one tell you:","a":"You are near a work zone: slow down","o":["You are near a work zone: slow down","A detour route for farm vehicles","A temporary emergency road closure","A park or picnic area ahead"],"why":"Orange signs mark work zones. Slow down even if no workers are in sight.","vis":"roadwork"},{"id":"sig-1mena9k","q":"This yellow diamond warns of:","a":"Pedestrians crossing ahead","o":["Pedestrians crossing ahead","A school bus stop ahead","A sidewalk that is ending","A hiking trail crossing"],"why":"Yellow diamonds warn about conditions ahead. This one warns people may be crossing.","vis":"ped"},{"id":"sig-1k64chx","q":"This blue sign tells you:","a":"A hospital is nearby","o":["A hospital is nearby","A rest area is ahead","A helicopter pad is ahead","Handicap parking only"],"why":"Blue signs give services. A white H on blue marks a hospital.","vis":"hospital"},{"id":"sig-12v7mh8","q":"This shield tells you what kind of road?","a":"An interstate highway","o":["An interstate highway","A Utah state route","A U.S. highway route","A county or city road"],"why":"The red, white, and blue shield marks an interstate.","vis":"shield"},{"id":"sig-zgz66p","q":"What shape and color are warning signs?","a":"Yellow diamonds","o":["Yellow diamonds","Red octagons","White rectangles","Green squares"],"why":"Warning signs are yellow diamonds with black symbols or words."},{"id":"sig-rrezky","q":"What color are work zone signs?","a":"Orange with black","o":["Orange with black","Yellow with red","Red with white","Green with white"],"why":"Work zone signs are orange with black lettering."},{"id":"sig-t4cao8","q":"What does a red circle with a slash through a picture mean?","a":"The pictured action is not allowed","o":["The pictured action is not allowed","The pictured action is required","The pictured thing is ahead","Do the pictured action with caution"],"why":"A slash means prohibited."},{"id":"sig-saxvaq","q":"A sign says CENTER LANE ONLY with left-turn arrows. The center lane is for:","a":"Left turns only, not for passing","o":["Left turns only, not for passing","Passing slower traffic ahead","Through traffic only, no turns","Bicycles and motorcycles only"],"why":"A shared center left-turn lane is for turning, not passing or through driving."},{"id":"sig-5dg59v","q":"Green, brown, and blue rectangular signs are:","a":"Guide signs","o":["Guide signs","Warning signs","Regulatory signs","Work zone signs"],"why":"Guide signs give directions, places, and services."},{"id":"sig-1sn0jka","q":"A sign has eight sides. What does it mean?","a":"Stop","o":["Stop","Yield","School zone","Railroad crossing"],"why":"A red eight-sided octagon is the STOP sign."},{"id":"sig-vk8gsx","q":"Which shape is a yield sign?","a":"A triangle pointing down","o":["A triangle pointing down","A circle","An eight-sided shape","A diamond"],"why":"The yield sign is a downward triangle."},{"id":"sig-8q0sxt","q":"Which shape and color is the railroad warning sign ahead of a crossing?","a":"Round and yellow with an X and RR","o":["Round and yellow with an X and RR","Square and green","Rectangular and white with black words","Orange and diamond"],"why":"The round yellow sign with an X and black RR warns of a crossing ahead."},{"id":"sig-shvx86","q":"Guide signs are what colors?","a":"Green, brown, or blue","o":["Green, brown, or blue","Red or orange","Yellow or black","White or purple"],"why":"Guide signs give directions and information in green, brown, or blue."},{"id":"sig-rxyetd","q":"Regulatory signs, which tell you the rules, are usually:","a":"White with black, red, or green lettering","o":["White with black, red, or green lettering","Green with white lettering and arrows","Orange with black lettering and symbols","Blue with white lettering and symbols"],"why":"Regulatory signs are mostly white with black, red, or green."},{"id":"sig-1c2z9c5","q":"Warning signs are usually which shape and color?","a":"A yellow diamond with black symbols","o":["A yellow diamond with black symbols","A white rectangle with red lettering","A green square with white lettering","A blue circle with white symbols"],"why":"Warning signs are usually yellow diamonds."},{"id":"sig-8vfa8f","q":"Work zone signs are usually:","a":"Orange with black symbols or words","o":["Orange with black symbols or words","Yellow with black symbols","Green with white words","Blue with white words"],"why":"Orange signs are for work zones."},{"id":"sig-1ye2vdz","q":"What do the shape and color of route signs tell you?","a":"The kind of road, like interstate, U.S., or state","o":["The kind of road, like interstate, U.S., or state","How fast the road lets you drive safely","Which exit is the next one coming up","Whether the road is a toll road or not"],"why":"Route signs show whether you are on an interstate, U.S., state, city, county, or local road."},{"id":"sig-1bz37pe","q":"A brown sign usually points to:","a":"Parks and recreation areas","o":["Parks and recreation areas","A hospital","A railroad crossing","A work zone"],"why":"Brown guide signs mark parks, recreation, and cultural sites (MUTCD)."},{"id":"sig-1eftw50","q":"A flagger in a work zone gives you directions. You should:","a":"Follow the flagger","o":["Follow the flagger","Follow the signs only","Ignore the flagger if the road looks clear","Drive around the flagger"],"why":"Always follow a flagger's directions."},{"id":"sig-1tdiva1","q":"When may you drive at normal speed again after a road work zone?","a":"After you see the END ROAD WORK sign","o":["After you see the END ROAD WORK sign","As soon as no workers are visible","After one mile","When another car passes you"],"why":"Obey work zone signs until you pass the end road work sign."},{"id":"sig-1xfr3qf","q":"A railroad crossing has two tracks. Is there always a sign saying so?","a":"No, so always look for more than one train","o":["No, so always look for more than one train","Yes, always","Yes, but only at night","No, and a second train never comes"],"why":"Not every crossing posts the number of tracks. Always check for a second train."},{"id":"sig-1lb99ri","q":"You see a Bicycle Crossing warning sign. What should you do?","a":"Slow down and watch for riders entering the road","o":["Slow down and watch for riders entering the road","Speed up to pass the riders before the crossing","Honk your horn to warn the riders of your car","Stop for the next 500 feet in every case"],"why":"Slow down and be ready to yield to bicyclists."},{"id":"sig-1jrom0c","q":"A red circle with a slash over a left-turn arrow means:","a":"No left turns","o":["No left turns","Left turns only","Left turn ahead","Slow down for a left curve"],"why":"The red circle with a slash means the pictured action is not allowed."},{"id":"sig-xqv2ll","q":"Where may you not make a U-turn, even with no sign?","a":"On a freeway or on railroad tracks","o":["On a freeway or on railroad tracks","In a quiet parking lot","On a wide road with a clear view","In your own driveway"],"why":"U-turns are illegal on freeways and on railroad crossings.","vis":"nouturn"},{"id":"sig-pll09w","q":"You see this sign with flashing lights and children are going to school. What is the speed limit?","a":"20 mph","o":["20 mph","25 mph","30 mph","15 mph"],"why":"Near schools, the limit is 20 mph when children are present or the lights flash.","vis":"school"},{"id":"sig-lo48od","q":"You see this warning sign but the crosswalk looks empty. What should you do?","a":"Slow down and be ready to stop for anyone who steps out","o":["Slow down and be ready to stop for anyone who steps out","Go at normal speed since no one is there","Honk to clear the area","Speed up to pass quickly"],"why":"A warning sign means people may cross, so slow down and watch.","vis":"ped"},{"id":"sig-1t3bn8d","q":"At this sign, there is no stop line or crosswalk painted. Where do you stop?","a":"Before the intersection","o":["Before the intersection","In the middle of the intersection","After the intersection","Anywhere you want"],"why":"If no line or crosswalk is marked, stop before the intersection.","vis":"stop"},{"id":"sig-1e5r6l0","q":"A sign shows a one-way arrow. What must you never do?","a":"Drive against the arrow","o":["Drive against the arrow","Stop at the corner","Turn right at the arrow","Park at the curb"],"why":"Never go the wrong way on a one-way street.","vis":"oneway"}]},{"id":"signals","name":"Signals & Markings","icon":"🚦","src":"Handbook: Signals & Pavement Markings","qs":[{"id":"sig-1loskh","q":"What does a steady red light mean?","a":"Stop behind the line and wait for green","o":["Stop behind the line and wait for green","Slow down and go if it is clear","Stop only if cars are coming up","Yield to cross traffic, then go"],"why":"Stop before the stop line or crosswalk. A right turn on red is allowed after a full stop unless posted.","vis":"red"},{"id":"sig-1fn2edf","q":"What does a steady yellow light mean?","a":"The light is about to turn red","o":["The light is about to turn red","The light is about to turn green","Speed up to clear the intersection","Proceed without caution"],"why":"Yellow warns that red is coming. Prepare to stop.","vis":"yellow"},{"id":"sig-84yz07","q":"What should you do at a flashing yellow light?","a":"Slow down and proceed with caution","o":["Slow down and proceed with caution","Stop completely for ten seconds","Treat it exactly like a stop sign","Treat it like a protected green arrow"],"why":"A flashing yellow means proceed carefully and be ready to stop.","vis":"flashyellow"},{"id":"sig-1wc2c7j","q":"What should you do at a flashing red light?","a":"Stop, check both ways, go when safe","o":["Stop, check both ways, go when safe","Slow down and go if it is clear","Stop only when it is dark out","Yield only to trucks and buses"],"why":"A flashing red acts like a stop sign.","vis":"flashred"},{"id":"sig-1f9bzh3","q":"What does a green arrow mean?","a":"Go the arrow's way, yielding to those inside","o":["Go the arrow's way, yielding to those inside","Go in any direction, since the way is clear","Go only after cross traffic has stopped for you","Yield to every car coming from your left"],"why":"A green arrow is a protected move, but you still yield to people already in the intersection.","vis":"greenarrow"},{"id":"sig-1qw039h","q":"What does a flashing yellow arrow mean?","a":"You may turn after yielding to oncoming traffic","o":["You may turn after yielding to oncoming traffic","You must stop before making the turn","You have a protected turn with no yielding","The signal is broken so treat it as dark"],"why":"A flashing yellow arrow allows a permitted turn. Yield first.","vis":"flashyellowarrow"},{"id":"sig-1hb9zx6","q":"What does a red left arrow mean?","a":"Left turns are not allowed; stay stopped","o":["Left turns are not allowed; stay stopped","Left turn allowed after a full stop","Left turn allowed when no cars come","Left turn allowed if you yield first"],"why":"A red arrow means that turn is prohibited while it shows.","vis":"redarrow"},{"id":"sig-10pwdbn","q":"On a vertical traffic signal, red is:","a":"On top","o":["On top","In the middle","On the bottom","On any lamp"],"why":"Vertical signals run red, yellow, green from top to bottom."},{"id":"sig-1wist0r","q":"A traffic signal is dark because of a power outage. What do you do?","a":"Stop, then yield to the vehicle on your right","o":["Stop, then yield to the vehicle on your right","Slow down and go if the road looks clear","Treat it as a flashing yellow and proceed","Follow the vehicle directly in front of you"],"why":"A dead signal means a full stop, then yield to the driver on your right unless an officer directs you."},{"id":"sig-1m2bz6y","q":"A police officer waves you through a red light. You should:","a":"Follow the officer","o":["Follow the officer","Stop for the red","Wait for the light to change","Go around the officer"],"why":"Officer directions override signals and signs."},{"id":"sig-1noxily","q":"When may you turn right on a red light?","a":"After a complete stop, unless a sign says no","o":["After a complete stop, unless a sign says no","After a rolling stop, if the road is clear","Only when a green arrow is also showing","Only when a police officer allows it"],"why":"Stop first, yield, then turn unless NO TURN ON RED is posted."},{"id":"sig-1kpqmv8","q":"On a green light, you still must:","a":"Yield to pedestrians and vehicles in the intersection","o":["Yield to pedestrians and vehicles in the intersection","Stop briefly to check for red-light runners","Slow to ten mph through every intersection","Flash your headlights to alert cross traffic"],"why":"A green light does not clear the intersection for you."},{"id":"sig-mzbu5l","q":"What does a solid yellow line pair like this mean?","a":"No passing in either direction","o":["No passing in either direction","Passing allowed from either side","Passing allowed from your side","A bicycle lane"],"why":"Double solid yellow lines forbid passing in both directions.","vis":"dblyellow"},{"id":"sig-1ey98a","q":"A broken yellow centerline means:","a":"Passing is allowed from your side when safe","o":["Passing is allowed from your side when safe","Passing is banned in both directions","Passing is allowed only during daylight","Cars may pass only on the right side"],"why":"Broken yellow lines permit passing from your side when it is safe.","vis":"dashyellow"},{"id":"sig-1y4y5q5","q":"What do white lane lines show?","a":"Traffic moves in the same direction","o":["Traffic moves in the same direction","Traffic moves in opposite directions","No passing at all","A work zone"],"why":"White lines separate traffic going the same way. Yellow separates opposite directions.","vis":"whitedash"},{"id":"sig-ozpbod","q":"Double white lines beside a carpool lane mean:","a":"Do not cross","o":["Do not cross","Cross to pass","Cross to exit anywhere","Bicycles only"],"why":"You cross only at marked access points.","vis":"dblwhite"},{"id":"sig-6aqjqj","q":"Where must you yield to pedestrians?","a":"In any crosswalk, marked or unmarked","o":["In any crosswalk, marked or unmarked","Only in crosswalks that are marked","Only at intersections with signals","Only in school zones and parking lots"],"why":"Yield to people in any crosswalk."},{"id":"sig-r5aj1y","q":"In a flex lane, what does a red X over the lane mean?","a":"The lane is closed to you","o":["The lane is closed to you","The lane is open for buses only","The lane is open for turns only","The lane is open to everyone"],"why":"A green arrow means use the lane. A red X means do not."},{"id":"sig-98mja9","q":"On a horizontal traffic signal, which light is on the left?","a":"Red","o":["Red","Green","Yellow","Blue"],"why":"On horizontal signals, red is on the left, yellow in the middle, and green on the right."},{"id":"sig-w43mev","q":"You are at this light and want to turn right. When may you turn?","a":"After a full stop, if no sign bans it and it is safe","o":["After a full stop, if no sign bans it and it is safe","Right away without stopping, if the road looks clear","Never, because a red light always means no turns","Only after the light has turned yellow again"],"why":"A right turn on red is allowed after a full stop unless a sign says no.","vis":"red"},{"id":"sig-rxzbfs","q":"An officer at the intersection tells you to stop, but your light is green. What do you do?","a":"Stop for the officer","o":["Stop for the officer","Go, since the light is green","Slow down and go","Honk and then go"],"why":"An officer's directions override signals."},{"id":"sig-2bxkw9","q":"You are going straight on a green light. An officer waves you to turn right. What do you do?","a":"Turn right as the officer says","o":["Turn right as the officer says","Keep going straight","Stop and wait for green","Turn left"],"why":"Follow the officer, even if it differs from the light."},{"id":"sig-1k3ergl","q":"What does this left-turn signal tell you about oncoming traffic?","a":"Oncoming traffic has a green light, so yield","o":["Oncoming traffic has a green light, so yield","Oncoming traffic must stop so you can turn","You have a protected turn with no yielding","The signal is broken so treat it as dark"],"why":"A flashing yellow arrow is a permitted turn. Yield to oncoming traffic and pedestrians.","vis":"flashyellowarrow"},{"id":"sig-1rioizz","q":"Which left-turn signal gives you a protected turn?","a":"A green arrow","o":["A green arrow","A flashing yellow arrow","A solid green light","A steady yellow light"],"why":"The green arrow is a protected move. Solid green and flashing yellow arrow are permitted turns."},{"id":"sig-6t4xhy","q":"A red arrow pointing right means:","a":"No right turns until another signal says go","o":["No right turns until another signal says go","Right turns allowed after a stop","Right turns only at night","Yield and turn right"],"why":"A red arrow means that turn is prohibited while it shows."},{"id":"sig-100rv3r","q":"A traffic signal has no stop line or crosswalk painted. Where do you stop at red?","a":"Before the intersection","o":["Before the intersection","In the middle of the intersection","Past the signal","Anywhere you like"],"why":"Stop before the intersection if no line or crosswalk is marked."},{"id":"sig-1362dx0","q":"A crosswalk has no paint at an intersection. Must you yield to pedestrians?","a":"Yes, unmarked crosswalks count too","o":["Yes, unmarked crosswalks count too","No, only marked ones count","Only if there are signs","Only during the day"],"why":"Yield to pedestrians in marked or unmarked crosswalks."},{"id":"sig-1w6uemw","q":"A dashed yellow line is on your side and a solid yellow line is on the other side. May you pass?","a":"Yes, when it is safe and no cars are coming","o":["Yes, when it is safe and no cars are coming","No, you may never pass where a solid line is","Yes, but only at night when roads are empty","No, unless you are driving a slow vehicle"],"why":"You may pass when the dashed line is on your side and it is safe."},{"id":"sig-6g6oru","q":"Yellow center lines separate traffic that is:","a":"Moving in opposite directions","o":["Moving in opposite directions","Moving the same direction","Parked","Bicycles only"],"why":"Yellow lines divide opposite directions. White lines divide the same direction."},{"id":"sig-xnuwzp","q":"Flex lanes may be marked with:","a":"Double-dashed yellow lines","o":["Double-dashed yellow lines","A single white line","Red lines","Solid blue lines"],"why":"Flex lanes often have double-dashed yellow lines on either side."},{"id":"sig-fcbt8v","q":"When are flex lanes used?","a":"During rush hours","o":["During rush hours","Only at night","Only in winter","Only on weekends"],"why":"Flex lanes open during rush hours. Check overhead signals first."},{"id":"sig-1e8guby","q":"How do you enter a shared center left-turn lane?","a":"Check mirrors, signal, check your left blind spot, steer in","o":["Check mirrors, signal, check your left blind spot, steer in","Speed up and cut across the traffic lanes","Stop in the traffic lane and wait for a gap","Turn on your hazards and move over quickly"],"why":"Signal, check your blind spot, and move in smoothly when it is clear."},{"id":"sig-dv2at0","q":"At a continuous flow intersection, how do you turn left?","a":"Cross at the first signal, then follow the far-left signal","o":["Cross at the first signal, then follow the far-left signal","Turn at the main intersection like normal","Stop in the median until all traffic clears","Wait at the first signal until it flashes"],"why":"Follow the first signal to cross the oncoming lanes and the second signal to finish the turn."},{"id":"sig-1j9d754","q":"In a diverging diamond interchange, traffic on the overpass or underpass:","a":"Briefly drives on the opposite side of the road","o":["Briefly drives on the opposite side of the road","Stops in the middle of the bridge for a signal","Drives on the left shoulder of the road","Uses one lane only, shared by all cars"],"why":"Cars cross to the other side of the road for a short stretch, then cross back."},{"id":"sig-9v2cmp","q":"At a thru-U-turn intersection, how do you go left?","a":"Go through, make a signalized U-turn, then turn right","o":["Go through, make a signalized U-turn, then turn right","Turn left at the main intersection as usual","Stop and turn around in the road, then go right","Take the freeway ramp and come back later"],"why":"Left turns are removed. You go through, U-turn, and turn right."},{"id":"sig-pzvd7q","q":"At a single-point urban interchange, when may you make a U-turn from the off-ramp?","a":"When you face a green arrow","o":["When you face a green arrow","Whenever it looks clear","When you face a red arrow","Never"],"why":"A U-turn from the off-ramp is legal only on a green arrow."},{"id":"sig-xppt26","q":"During a power outage at a single-point urban interchange, you should:","a":"Proceed with extreme caution and courtesy","o":["Proceed with extreme caution and courtesy","Treat it as a regular four-way stop","Speed through quickly","Wait for a tow truck"],"why":"The handbook says it is not treated as a four-way stop. Use extreme caution and courtesy."},{"id":"sig-1vlxtd7","q":"Does a green light mean it is safe to go?","a":"No, check that the path is clear before you go","o":["No, check that the path is clear before you go","Yes, always","Yes, if you are in the right lane","Only on freeways"],"why":"On green, still make sure the intersection is clear and cross traffic has stopped."},{"id":"sig-eudsaw","q":"A vertical traffic signal is red on top. Which color is on the bottom?","a":"Green","o":["Green","Yellow","Red","Blue"],"why":"Vertical lights run red, yellow, green from top to bottom."}]},{"id":"rightway","name":"Right-of-Way","icon":"🔀","src":"Handbook: Yielding Right-of-Way","qs":[{"id":"rig-1rqgo3e","q":"Two cars reach a four-way stop at the same time. Who goes first?","a":"The driver on the right","o":["The driver on the right","The driver on the left","The larger vehicle","The driver who honks first"],"why":"Yield to the driver on your right when you arrive together."},{"id":"rig-1ps6id2","q":"When turning left at an intersection, you must yield to:","a":"Oncoming traffic","o":["Oncoming traffic","Cars behind you","Only pedestrians","No one on a green light"],"why":"Left-turners yield to oncoming vehicles and pedestrians."},{"id":"rig-rwjtrt","q":"When pulling out of a driveway onto a public road, you must:","a":"Yield to traffic on the road","o":["Yield to traffic on the road","Go first because you are moving slowly","Honk and go","Use the left lane"],"why":"Traffic on the public road has priority."},{"id":"rig-n1t2n2","q":"When entering the interstate from a ramp, you must:","a":"Yield to interstate traffic","o":["Yield to interstate traffic","Expect others to move over for you","Stop at the end of the ramp","Merge at any speed"],"why":"You must find a gap and yield to traffic already on the highway."},{"id":"rig-1lxtwy1","q":"Before entering an intersection, you should look:","a":"Left, right, then left again","o":["Left, right, then left again","Straight ahead, then to the right","Right, then left, then straight","Only at the signal or sign ahead"],"why":"Check for cross traffic, pedestrians, and obstructions."},{"id":"rig-1dhhyo9","q":"An oncoming car has its left turn signal on. You should:","a":"Wait until you see it actually turn","o":["Wait until you see it actually turn","Assume it will turn and go ahead","Speed up to pass in front of it","Flash your lights and start moving"],"why":"Do not rely on signals alone. Wait to see what the driver does."},{"id":"rig-7s9m40","q":"Which way does traffic move around a Utah roundabout?","a":"Counterclockwise","o":["Counterclockwise","Clockwise","Whichever lane is open","Straight through the center"],"why":"Utah roundabouts flow counterclockwise."},{"id":"rig-1i23ske","q":"As you enter a roundabout, you must:","a":"Slow down and yield to traffic and pedestrians","o":["Slow down and yield to traffic and pedestrians","Speed up to merge before traffic arrives","Stop in the center until traffic clears","Honk once and enter ahead of traffic"],"why":"Slow on approach and yield before entering."},{"id":"rig-1ltx4fd","q":"Under the 2026 law change, a turn signal in a roundabout is:","a":"Not required","o":["Not required","Required at every exit","Required only at night","Required only on entry"],"why":"HB 128 (2026) removed the requirement to signal while turning in a roundabout."},{"id":"rig-13jn4yn","q":"A pedestrian is crossing with a white cane or guide dog. You must:","a":"Come to a complete stop","o":["Come to a complete stop","Slow and honk","Go around them","Proceed if they are far away"],"why":"Always stop for pedestrians who are visually impaired."},{"id":"rig-17iftov","q":"A car ahead of you is stopped at a crosswalk. You should:","a":"Stop behind it and never pass","o":["Stop behind it and never pass","Pass slowly on the left if it is clear","Pass on the right using the shoulder","Honk and wait for the driver to move"],"why":"Passing a car stopped at a crosswalk is how pedestrians get hit."},{"id":"rig-y3z5h7","q":"An emergency vehicle with flashing lights comes up behind you. You should:","a":"Pull to the right and stop until it passes","o":["Pull to the right and stop until it passes","Speed up and get out of its way","Stop in your lane and set the brake","Move to the left lane and keep going"],"why":"Yield right-of-way by moving right and stopping."},{"id":"rig-1qvew2u","q":"How far before a turn may you enter a shared center left-turn lane?","a":"No more than 500 feet","o":["No more than 500 feet","No more than 50 feet","No more than 1,000 feet","As far ahead as you want"],"why":"Do not enter the shared lane more than 500 feet before your turn."},{"id":"rig-dpqrqh","q":"You and a car on your left and a car on your right reach a four-way stop at the same time. Who goes first?","a":"The car on your right","o":["The car on your right","The car on your left","The car that is biggest","The car that honks first"],"why":"When you arrive together, yield to the driver on your right."},{"id":"rig-ci1jgz","q":"You arrive at a four-way stop after another driver who is already there. Who goes first?","a":"The driver who arrived first","o":["The driver who arrived first","The driver on your right","The faster car","The bigger vehicle"],"why":"Yield to a driver who reaches the intersection before you."},{"id":"rig-12meax1","q":"You turn left on a flashing yellow arrow. A pedestrian is in the street you are entering. What must you do?","a":"Yield to the pedestrian","o":["Yield to the pedestrian","Honk to warn them","Speed up to turn first","Turn only if you have the bigger car"],"why":"Yield to pedestrians when turning."},{"id":"rig-14hj2j2","q":"You are turning right. A bicyclist is going straight beside you. Who yields?","a":"You yield to the bicyclist","o":["You yield to the bicyclist","The bicyclist yields to you","Whoever is faster","Nobody"],"why":"Yield to bicyclists at right turns and in intersections."},{"id":"rig-1y12ez6","q":"A bike path crosses the road ahead. What must you do?","a":"Yield to bicyclists on the path","o":["Yield to bicyclists on the path","Honk to warn them","Speed up to pass","Ignore it because it is not a street"],"why":"Yield where a bike path or bike lane crosses a road."},{"id":"rig-1a6tiqz","q":"A car in the lane next to you stops at a crosswalk. What should you do?","a":"Stop too, since a pedestrian may be hidden","o":["Stop too, since a pedestrian may be hidden","Go around it if the lane looks clear","Honk so the car moves on right away","Speed up to pass before the pedestrian steps out"],"why":"Pedestrians can be hidden by the stopped car. Stop and look."},{"id":"rig-13782zo","q":"A mid-block crosswalk has no signs or lights. What should you do?","a":"Watch for it and yield to pedestrians","o":["Watch for it and yield to pedestrians","Ignore it since it has no markings at all","Drive faster to clear it before anyone steps out","Stop only if you see paint on the road"],"why":"Mid-block crosswalks may have few markings, so watch for them."},{"id":"rig-1kzkp9y","q":"You want to pull away from a parallel parking space. Who has the right-of-way?","a":"Traffic already on the road","o":["Traffic already on the road","You, since you are signaling","Whoever is bigger","Pedestrians only"],"why":"Yield to traffic when pulling from the curb."},{"id":"rig-rmav5m","q":"The light turns green but a pedestrian is still crossing. What do you do?","a":"Wait until they clear","o":["Wait until they clear","Go around them","Honk","Go because you have a green"],"why":"Yield to people still in the intersection."},{"id":"rig-11j4vuf","q":"Another driver does not yield to you. What should you do?","a":"Slow down and let them go to avoid a crash","o":["Slow down and let them go to avoid a crash","Insist on your right-of-way","Speed up","Flash your lights and keep going"],"why":"Never assume you have the right-of-way."},{"id":"rig-sz8gfw","q":"As you enter a roundabout, you must yield to:","a":"Traffic already in the circle and pedestrians","o":["Traffic already in the circle and pedestrians","Only large trucks and buses in the circle","Nobody, because you have priority entering","Only cars coming from your right side"],"why":"Slow down and yield to traffic and pedestrians before entering."},{"id":"rig-bqrywo","q":"In a roundabout, you may enter when:","a":"Pedestrians are clear and a gap opens","o":["Pedestrians are clear and a gap opens","The car behind you honks to move you along","You are in a hurry and the center is empty","Nobody is on the far side of the circle"],"why":"Wait for pedestrians and a gap in circulating traffic."},{"id":"rig-1s49h3k","q":"A fire engine has stopped on your block for an alarm. May you park there?","a":"No, do not drive or park on the same block","o":["No, do not drive or park on the same block","Yes, if you leave plenty of room for the engine","Yes, if you stay inside your car with the engine on","Yes, but only on the opposite side of the street"],"why":"Do not drive or park on the same block where a fire vehicle has stopped for an alarm."},{"id":"rig-e37cl7","q":"Two cars come to opposite ends of a single-lane bridge. Who goes first?","a":"The first driver to arrive","o":["The first driver to arrive","The larger vehicle","The faster car","The car on the right"],"why":"On single-lane bridges, the first driver to arrive goes first."},{"id":"rig-1hwcee4","q":"You are on a narrow mountain road and meet a car going uphill while you go downhill. Who should back up or yield?","a":"You yield to the uphill car","o":["You yield to the uphill car","The uphill car yields","The faster driver","Nobody yields"],"why":"The downhill driver yields to uphill traffic."}]},{"id":"speed","name":"Speed & Visibility","icon":"🌙","src":"Handbook: Speed, Night Driving, Challenges","qs":[{"id":"spe-14s71ji","q":"With no sign and no hazards, the limit in a business or residential area is:","a":"25 mph","o":["25 mph","20 mph","30 mph","35 mph"],"why":"The handbook gives 25 mph for business or residential areas without signs."},{"id":"spe-jfxrg9","q":"Near a school during recess or when children arrive or leave, the limit is:","a":"20 mph","o":["20 mph","15 mph","25 mph","30 mph"],"why":"School zone speeds are 20 mph when children are present."},{"id":"spe-yhkakj","q":"The basic speed law says you must never drive:","a":"Faster than is reasonable and prudent","o":["Faster than is reasonable and prudent","Faster than the posted limit at night","Faster than most of the cars around","Faster than 55 mph on any highway"],"why":"You must adjust speed to conditions even below the posted limit."},{"id":"spe-ymyg07","q":"Rural Utah interstates can have limits as high as:","a":"80 mph","o":["80 mph","70 mph","65 mph","90 mph"],"why":"Interstate limits run 65 to 80 mph depending on the area."},{"id":"spe-pwadl8","q":"Driving too slowly can get you a ticket if you:","a":"Hold up traffic","o":["Hold up traffic","Go below the limit at all","Use the right lane","Use cruise control"],"why":"Impeding traffic is a violation."},{"id":"spe-2hase4","q":"When must headlights be on?","a":"From sunset to sunrise, or when visibility is low","o":["From sunset to sunrise, or when visibility is low","Only after midnight or when it is raining","Only on freeways and highways after dark","Only when other drivers have their lights on"],"why":"Lights are required from sunset to sunrise and in low visibility."},{"id":"spe-1ptwum7","q":"How close to an oncoming car should you dim your high beams?","a":"Within 500 feet","o":["Within 500 feet","Within 1,000 feet","Within 100 feet","Within 50 feet"],"why":"Dim within 500 feet of oncoming vehicles and within 300 feet when following."},{"id":"spe-16fjhfy","q":"If oncoming headlights blind you, look:","a":"Toward the right edge of the road","o":["Toward the right edge of the road","Straight at the oncoming headlights","Toward the left edge of the road","Down at the dashboard instruments"],"why":"Looking right keeps you in your lane without staring into the lights."},{"id":"spe-1q6rche","q":"At night you should:","a":"Not wear sunglasses or tinted lenses","o":["Not wear sunglasses or tinted lenses","Wear sunglasses to reduce the glare","Drive faster to finish the trip sooner","Use only your parking lights in town"],"why":"The handbook advises no sunglasses or colored lenses at night."},{"id":"spe-kay1q0","q":"Hydroplaning can begin at speeds above about:","a":"35 mph","o":["35 mph","20 mph","50 mph","60 mph"],"why":"Tires can ride up on water above 35 mph."},{"id":"spe-c22lmg","q":"Black ice often looks like:","a":"A wet spot on the road","o":["A wet spot on the road","Dry pavement with white edges","Fresh snow on the road","Loose gravel on the road"],"why":"Black ice is hard to see and can look just wet."},{"id":"spe-17u3e8p","q":"In fog, rain, or snow you should use:","a":"Low beams","o":["Low beams","High beams","Parking lights","No lights"],"why":"High beams reflect off the fog or snow. Use low beams."},{"id":"spe-e7s4jm","q":"Metal-stud snow tires are allowed in Utah during which dates?","a":"October 15 through March 31","o":["October 15 through March 31","November 1 through April 30","Any time of year","September 1 through February 28"],"why":"Studded tires are legal October 15 through March 31."},{"id":"spe-cx6ndv","q":"Speeding fines in highway work zones are at least:","a":"Twice the normal fine","o":["Twice the normal fine","The same as normal","Three times the normal fine","A flat $500"],"why":"Courts must impose at least double in a highway construction zone."},{"id":"spe-1iwdx63","q":"On an icy road, which speed may be too fast?","a":"10 mph","o":["10 mph","25 mph","35 mph","45 mph"],"why":"The handbook says even 10 mph can be too fast on ice."},{"id":"spe-ymy9m8","q":"No sign is posted and you are on a major highway. The limit is:","a":"55 mph","o":["55 mph","65 mph","45 mph","70 mph"],"why":"Major highways are 55 mph unless posted otherwise."},{"id":"spe-fxvc6q","q":"Utah rural interstate speed limits can be:","a":"65, 70, 75, or 80 mph","o":["65, 70, 75, or 80 mph","Always 55 mph, the same as other highways","Only 60 or 65 mph in the whole state","From 85 to 90 mph on the longest stretches"],"why":"Rural interstate limits are 65, 70, 75, or 80 mph, as posted."},{"id":"spe-17ryh51","q":"A transition zone on the road between speed limits is marked by:","a":"Pavement markings and extra signs","o":["Pavement markings and extra signs","A police officer standing beside the road","A row of orange cones across the road","A flashing yellow light above the lane"],"why":"Transition zones use markings and signs to show a change."},{"id":"spe-1v0wssq","q":"When does the 20 mph school limit apply?","a":"At recess, arrival and dismissal, or when lights flash","o":["At recess, arrival and dismissal, or when lights flash","Only on weekends when children play outside","Only at night when it is hard to see","Only when a school bus is in sight"],"why":"The 20 mph limit is for recess, school opening and closing hours, or when flashing lights operate."},{"id":"spe-t9403r","q":"The school zone lights are flashing. What must you do?","a":"Obey the lower school zone speed limit","o":["Obey the lower school zone speed limit","Drive the normal posted limit for the road","Stop for ten minutes before going on","Pass slowly on the right shoulder"],"why":"Flashing school zone lights mean the lower speed limit is in effect."},{"id":"spe-1bd4657","q":"Which of these is a time to slow down?","a":"When you approach a hilltop","o":["When you approach a hilltop","When the road is wide and empty","When you see a green light","On a wide, empty road in daylight"],"why":"Slow down for curves, hilltops, narrow roads, intersections, and crossings."},{"id":"spe-1uoowg0","q":"You are approaching a curve. What should you do?","a":"Slow down before you reach it","o":["Slow down before you reach it","Speed up to get through it","Brake in the middle of it","Stay at the same speed no matter what"],"why":"Slow before the curve so you stay in control and in your lane."},{"id":"spe-cegjpu","q":"You see people walking beside the road. What should you do?","a":"Slow down and give them room","o":["Slow down and give them room","Honk","Speed up to pass","Stay at the same speed"],"why":"Slow down for special hazards like people walking beside the road."},{"id":"spe-5uhzk8","q":"You see an authorized vehicle with flashing red, red and white, or red and blue lights ahead. You should:","a":"Slow down","o":["Slow down","Speed up","Honk","Flash your high beams"],"why":"Slow down when approaching authorized vehicles with flashing lights."},{"id":"spe-1xsi6b3","q":"Open highway, rain, and night. Even the 25 mph speed may be:","a":"Too fast","o":["Too fast","Too slow","Perfect","Illegal"],"why":"In rain at night on an open road, 25 mph may still be too fast."},{"id":"spe-1o31rmg","q":"You dim your high beams when following another car within:","a":"300 feet","o":["300 feet","100 feet","500 feet","1,000 feet"],"why":"Dim your high beams within 300 feet of the car ahead, and within 500 feet of oncoming cars."},{"id":"spe-qky17s","q":"At night, how much more following distance should you add?","a":"At least 2 more seconds","o":["At least 2 more seconds","None","Half a second","One tenth of a second"],"why":"Add at least 2 seconds more at night."},{"id":"spe-1ucx23d","q":"A car ahead of you passes a sign. You reach the same sign 1 second later. What should you do?","a":"Slow down, since you are following too closely","o":["Slow down, since you are following too closely","Keep going, since 1 second is enough room","Speed up to pass the car ahead of you","Flash your high beams so it moves over"],"why":"The handbook uses a two second following gap. One second is too close."},{"id":"spe-11phh36","q":"Which parts of the road freeze first in winter?","a":"Bridges, ramps, and overpasses","o":["Bridges, ramps, and overpasses","Parking lots and wide shopping center lots","Dry gravel roads on the edge of town","Roads that run under the tree branches"],"why":"Bridges, ramps, and overpasses freeze first because air flows under them."},{"id":"spe-pkj8ar","q":"Your car is front-wheel drive. How should you use snow or all-season tires?","a":"On all four wheels","o":["On all four wheels","On the front wheels only","On the rear wheels only","On none, since studs are enough"],"why":"The handbook says put snow or all-season tires on all four wheels."},{"id":"spe-1e05w1","q":"Bleeding tar on hot days is:","a":"Slippery","o":["Slippery","Safe to drive on","Only a problem at night","Good for traction"],"why":"Tar can bleed up in hot weather and make the road slippery."},{"id":"spe-8og5q9","q":"Most crashes happen between what hours?","a":"2 p.m. and 6 p.m.","o":["2 p.m. and 6 p.m.","Midnight and 4 a.m.","6 a.m. and 9 a.m.","10 a.m. and noon"],"why":"Most crashes occur from 2 p.m. to 6 p.m."},{"id":"spe-iffbqz","q":"Where is the highest crash rate?","a":"Shopping and business areas","o":["Shopping and business areas","Rural farm roads with little traffic","Mountain passes in the winter months","Freeways late at night in good weather"],"why":"Crash rates are highest in shopping and business areas."},{"id":"spe-65pkud","q":"In Utah two-car fatal crashes, how many of the drivers killed were not at fault?","a":"Over half","o":["Over half","About one in ten","About one in four","Almost none"],"why":"Over half of drivers killed in two-car crashes were not at fault, so drive defensively."},{"id":"spe-572z37","q":"In work zones, who is most often killed or hurt?","a":"Drivers, passengers, and pedestrians","o":["Drivers, passengers, and pedestrians","Only the road workers on the crew","Only the truck drivers on the route","Only the flaggers who direct traffic"],"why":"Over 80 percent of the people hurt or killed are drivers, passengers, or pedestrians."},{"id":"spe-1vqoyug","q":"In a work zone you should:","a":"Leave extra room and obey signs until END ROAD WORK","o":["Leave extra room and obey signs until END ROAD WORK","Tailgate so traffic moves along faster","Ignore signs when no workers are in sight","Stop and wait for the workers to wave"],"why":"Do not tailgate, and obey posted signs until the end of the work zone."},{"id":"spe-1rbzh7","q":"At a short-term work zone signal, you should stop where?","a":"At the white line, if one is marked","o":["At the white line, if one is marked","In the middle of the work zone","Beside the barrier","Past the signal"],"why":"Stop at the white line if one is marked."}]},{"id":"freeway","name":"Freeways & Merging","icon":"🛣️","src":"Handbook: Freeways, Ramps & Express Lanes","qs":[{"id":"fre-1cywegr","q":"You missed your freeway exit. What should you do?","a":"Take the next exit","o":["Take the next exit","Back up on the shoulder","Make a U-turn across the median","Stop and wait for a gap"],"why":"Never back up or turn around on a freeway."},{"id":"fre-1y91zta","q":"Using an entrance ramp to leave the freeway is:","a":"Illegal, even in a traffic jam","o":["Illegal, even in a traffic jam","Legal if you use your turn signal","Legal during heavy traffic jams","Legal at night when it is empty"],"why":"Entrance ramps are for entering only."},{"id":"fre-xsw6am","q":"What following distance should you keep on the freeway?","a":"At least two seconds","o":["At least two seconds","At least one second","Half a second at 70 mph","At least ten seconds always"],"why":"Keep at least two seconds and more in bad weather."},{"id":"fre-mo45sh","q":"What is the lane outside the solid white edge line for?","a":"Emergencies only","o":["Emergencies only","Passing","Picking up passengers","Slow vehicles"],"why":"Passing or stopping there to pick people up is illegal."},{"id":"fre-1m194vo","q":"You are driving in the left lane and a faster car comes up behind you. You should:","a":"Move right when it is safe","o":["Move right when it is safe","Stay and speed up","Brake to teach them a lesson","Flash your high beams"],"why":"Left-lane drivers move right so they do not impede traffic."},{"id":"fre-22tx4g","q":"Where may you enter or leave an I-15 express lane?","a":"Where the white lines are dotted","o":["Where the white lines are dotted","Anywhere you see an open space","Only at the very end of the lane","Anywhere you signal first"],"why":"Use the dotted-line access points only."},{"id":"fre-6ug33s","q":"Crossing the double white lines beside an express lane is:","a":"Illegal","o":["Illegal","Legal when traffic is light","Legal if you signal","Legal for trucks only"],"why":"Double white lines mean do not cross."},{"id":"fre-odjbqp","q":"How many people must a car carry to use the I-15 express lane for free?","a":"Two or more","o":["Two or more","Three or more","Four or more","One"],"why":"Cars with two or more occupants may use the lane free."},{"id":"fre-146m6td","q":"In a flex lane, a green arrow means:","a":"The lane is open to you","o":["The lane is open to you","The lane is closed to you","You must exit at the next ramp","The lane is for buses only"],"why":"Check overhead signals before entering."},{"id":"fre-v1k5be","q":"On an entrance ramp you should use the acceleration lane to:","a":"Match the speed of traffic","o":["Match the speed of traffic","Stop and wait for a big gap","Pass the slower cars ahead","Slow down before you merge"],"why":"Match speed, find a gap, then merge."},{"id":"fre-zbn76n","q":"A ramp meter shows red and green. How many cars go per green?","a":"One, unless posted otherwise","o":["One, unless posted otherwise","Two, unless posted otherwise","As many as will fit in the gap","Three, unless posted otherwise"],"why":"One vehicle per green unless signs say otherwise."},{"id":"fre-vgr58i","q":"What is a runaway truck ramp for?","a":"Emergencies only, no stopping or parking","o":["Emergencies only, no stopping or parking","Rest stops for tired truck drivers","Overflow parking for big rigs","Extra passing lane for slow trucks"],"why":"Use it only in an emergency and never park on it."},{"id":"fre-b70dsb","q":"On an exit ramp, you may drive:","a":"No faster than the posted limit","o":["No faster than the posted limit","As fast as the freeway traffic","Ten over the limit if clear","Whatever speed feels safe"],"why":"The posted limit applies on exit ramps too."},{"id":"fre-1gjc1ti","q":"Crossing the solid white line into the striped gore area is:","a":"Illegal","o":["Illegal","Fine for passing","Fine to exit late","Fine in traffic"],"why":"The gore area is not for driving."},{"id":"fre-bb1di8","q":"How long is an express lane access point, marked by white dotted lines?","a":"About 3,000 feet","o":["About 3,000 feet","About 100 feet","About 500 feet","About 10 miles"],"why":"Access points are about 3,000 feet long and sit near most interchanges."},{"id":"fre-1co5wkx","q":"How can you get out of the I-15 express lane safely before your exit?","a":"Exit one interchange before the one you want","o":["Exit one interchange before the one you want","Cross the double white line near your exit","Slow down in the express lane as you go","Stop on the shoulder and wait for a gap"],"why":"The handbook says leave the express lane one interchange early."},{"id":"fre-zouo83","q":"Which one-person vehicle may use the I-15 express lane for free?","a":"A motorcycle","o":["A motorcycle","A pickup truck","A passenger car","A delivery van"],"why":"Motorcycles, buses, and cars with two or more people may use it free."},{"id":"fre-13zvttq","q":"A single driver with no passengers wants to use the I-15 express lane. What is needed?","a":"A UDOT express pass with an active account","o":["A UDOT express pass with an active account","A parking permit","A police pass","Nothing, it is free for everyone"],"why":"Solo drivers need a UDOT express pass linked to a credit or debit account."},{"id":"fre-1sebzfq","q":"A police car with flashing lights is behind you in the express lane. What may you do?","a":"Move right out of the lane when safe","o":["Move right out of the lane when safe","Cross the double white line at once","Stop in the lane","Speed up"],"why":"You may leave the express lane to the right when safe if followed by an emergency vehicle."},{"id":"fre-1t1wx1e","q":"On a freeway, you may change lanes only to:","a":"Pass, exit, or follow a route change","o":["Pass, exit, or follow a route change","Look at the scenery or avoid a slow truck","Slow down for traffic that is merging ahead","Move away from a truck that is passing"],"why":"Lane changes should have a clear purpose: passing, exiting, or a route change."},{"id":"fre-10qy3wq","q":"You stay in the left lane of a freeway and a faster car comes up behind you. You may be cited for:","a":"Impeding traffic","o":["Impeding traffic","Speeding","Reckless driving","Tailgating"],"why":"Left-lane drivers must move right when approached from behind."},{"id":"fre-oea4ul","q":"When should you slow down to leave a freeway?","a":"After you enter the exit lane","o":["After you enter the exit lane","Before you reach the exit lane, on the main road","Anywhere you like","Right at the exit sign"],"why":"Keep steady speed on the freeway, then slow down in the exit or deceleration lane."},{"id":"fre-r61z48","q":"After you merge onto the freeway, you should:","a":"Cancel your turn signal","o":["Cancel your turn signal","Leave it on for a mile","Honk twice","Flash your lights"],"why":"Cancel the signal once you have merged."},{"id":"fre-1imtag","q":"The 'meter on' sign at a ramp meter is dark. What should you do?","a":"Enter as usual","o":["Enter as usual","Stop and wait for green","Wait for a police officer","Turn around"],"why":"Meters work only when the sign is lit."},{"id":"fre-kdy7c7","q":"How fast should you drive on a freeway?","a":"Near the speed of other traffic, but never over the limit","o":["Near the speed of other traffic, but never over the limit","As fast as the traffic in the left lane goes","Much slower than traffic to stay extra safe","Faster than traffic so you can merge easily"],"why":"Match traffic but never go over the posted speed."},{"id":"fre-14rt8nh","q":"Driving on the emergency lane outside the solid white line to pass is:","a":"Illegal","o":["Illegal","Allowed for trucks","Allowed in traffic jams","Allowed at night"],"why":"The emergency lane is for emergencies only. Passing or picking up passengers there is illegal."},{"id":"fre-mddobd","q":"You are on an off-ramp. How fast may you go?","a":"No faster than the posted limit","o":["No faster than the posted limit","Freeway speed until the very bottom","As fast as you like if no one is near","10 mph under the limit at all times"],"why":"The posted limit applies on exit ramps too."},{"id":"fre-4dst7q","q":"A runaway vehicle ramp is for:","a":"Emergencies only, never for parking","o":["Emergencies only, never for parking","Passing slower trucks on long upgrades","Resting during a long drive on a hill","Slow trucks that want to leave the road"],"why":"Do not stop, stand, or park on the ramp or in its path."}]},{"id":"alcohol","name":"Alcohol & Drugs","icon":"🚫","src":"Handbook: Alcohol & Drugs","qs":[{"id":"alc-nqw32m","q":"Utah's legal limit for adult drivers is over what BAC?","a":"0.05","o":["0.05","0.08","0.10","0.04"],"why":"Utah's per se limit is 0.05, lower than most states."},{"id":"alc-msochy","q":"For a driver under 21, how much alcohol is allowed?","a":"None measurable","o":["None measurable","Less than 0.02","Under 0.05 BAC","One drink with a meal"],"why":"Utah's Not-a-Drop law bans any measurable alcohol under 21."},{"id":"alc-1jir98b","q":"Not-a-Drop first offense for a driver under 21 means all driving privileges are denied for:","a":"6 months","o":["6 months","90 days","1 year","30 days"],"why":"The first offense is a six month denial."},{"id":"alc-x9jcp1","q":"An under-21 driver with a first DUI gets an automatic ignition interlock for:","a":"3 years","o":["3 years","1 year","2 years","6 months"],"why":"The handbook's sample question gives 3 years."},{"id":"alc-1n7xu1t","q":"A first DUI at age 21 or older brings a license suspension of:","a":"120 days","o":["120 days","30 days","1 year","18 months"],"why":"First DUI is 120 days. Later DUIs are 2 years."},{"id":"alc-1g8sz3c","q":"Refusing a chemical test brings a revocation of how long for a first offense (adult)?","a":"18 months","o":["18 months","120 days","6 months","3 years"],"why":"Under implied consent, refusal costs 18 months, and 36 months after that."},{"id":"alc-16lx9wb","q":"Alcohol starts affecting your driving:","a":"With the first drink","o":["With the first drink","After three drinks","Only above 0.08","Only on an empty stomach"],"why":"Impairment begins with the first drink."},{"id":"alc-yppmfh","q":"Extreme DUI means a BAC of at least:","a":"0.16","o":["0.16","0.12","0.10","0.20"],"why":"Utah defines extreme DUI as 0.16 or higher."},{"id":"alc-1s99u87","q":"Can you be convicted of impaired driving with a BAC under the limit?","a":"Yes, if alcohol or drugs impair your driving","o":["Yes, if alcohol or drugs impair your driving","No, only the BAC number counts in court","Only if you are driving after dark","Only if you are under 21 years old"],"why":"Impaired driving below the limit still breaks the law."},{"id":"alc-qwudv0","q":"An ignition interlock device:","a":"Requires a breath sample to start and run the car","o":["Requires a breath sample to start and run the car","Locks the doors automatically if there is a crash","Limits the car's top speed to 55 mph","Records every trip you take for the court"],"why":"The device checks your breath before the engine starts."},{"id":"alc-194vor6","q":"A prescription drug that causes drowsiness:","a":"May make driving unsafe, so ask your doctor","o":["May make driving unsafe, so ask your doctor","Is safe to drive on if it is prescribed","Is only a problem if you also drink","Is only a problem on long road trips"],"why":"Medication can cause drowsiness. Doctors may advise against driving."},{"id":"alc-y23y6f","q":"A person under 21 convicted of alcohol possession or consumption loses the license for:","a":"1 year for a first conviction","o":["1 year for a first conviction","90 days","6 months","2 years for a first conviction"],"why":"The suspension is 1 year first and 2 years after."},{"id":"alc-15wvvay","q":"Boating under the influence carries:","a":"The same penalties as driving under the influence","o":["The same penalties as driving under the influence","Lesser penalties than driving under the influence","No penalties because it is not a road","Only a warning for a first offense"],"why":"Utah treats boating DUI like driving DUI."},{"id":"alc-k8pszp","q":"Mixing alcohol and drugs is:","a":"Dangerous, never combine them","o":["Dangerous, never combine them","Safe in small amounts","Fine if the drugs are prescribed","Safe if you eat first"],"why":"Combining them multiplies the effect."},{"id":"alc-191ykte","q":"Vision is affected at what BAC for all drivers?","a":"0.02","o":["0.02","0.05","0.08","0.16"],"why":"The handbook says vision is affected at 0.02, well below the legal limit."},{"id":"alc-1rmkbmq","q":"Alcohol and impairing drugs are involved in about what share of yearly fatal crashes?","a":"About 40 percent","o":["About 40 percent","About 5 percent","About 90 percent","About 1 percent"],"why":"Alcohol and drugs are involved in about 40 percent of deadly crashes."},{"id":"alc-1m2db6t","q":"What is the BAC limit for commercial driver license holders?","a":"0.04","o":["0.04","0.05","0.08","0.10"],"why":"Drivers with CDLs face a 0.04 limit."},{"id":"alc-bm5s2e","q":"A second Not-a-Drop offense within 10 years brings what loss of driving?","a":"Two years, or until age 21, whichever is longer","o":["Two years, or until age 21, whichever is longer","Six months, the same as the first offense","One year, whether or not you turn 21","Ninety days with a defensive driving course"],"why":"A second offense is a longer loss than the first."},{"id":"alc-31zfo4","q":"A teen age 15 is convicted of drinking alcohol for the second time. How long is the license suspended?","a":"Two years","o":["Two years","One year","Six months","Ninety days"],"why":"A second or later conviction is a 2 year suspension."},{"id":"alc-1d5vp1o","q":"What does a driver under 21 need to get driving privileges back after a Not-a-Drop offense?","a":"A substance abuse program assessment or a class","o":["A substance abuse program assessment or a class","A letter from a parent asking for it back","A new driving test and a fine of $50","Nothing, just wait until the time runs out"],"why":"Reinstatement needs a program assessment or proof of a Prime For Life class."},{"id":"alc-x9v21w","q":"After a DUI arrest, an officer may take your license. The suspension starts on which day?","a":"The 45th day after the arrest","o":["The 45th day after the arrest","The day of the arrest","The 5th day","The 120th day"],"why":"The suspension begins on the 45th day after arrest."},{"id":"alc-l59z6u","q":"A first DUI at age 21 or older usually brings an ignition interlock for:","a":"18 months","o":["18 months","3 years","6 months","10 years"],"why":"An adult first DUI is 18 months. Under 21 it is 3 years."},{"id":"alc-qp4bt3","q":"A second DUI brings an ignition interlock for:","a":"2 years","o":["2 years","6 months","18 months","10 years"],"why":"A second or later DUI brings a 2 year interlock."},{"id":"alc-m1i316","q":"An ignition interlock device must be serviced at least how often?","a":"Every 60 days","o":["Every 60 days","Every 6 months","Every year","Every week"],"why":"It must be serviced every 60 days."},{"id":"alc-1qfomej","q":"A driver blows into an interlock and it shows alcohol. What happens?","a":"The requirement is extended 60 days","o":["The requirement is extended 60 days","Nothing, the car just starts","The device resets for free","The car gets a free start"],"why":"Alcohol-positive start attempts extend the interlock for 60 days."},{"id":"alc-18mfwzf","q":"A person on alcohol-restricted status drives with any measurable alcohol. What is the penalty?","a":"A 1 year revocation","o":["A 1 year revocation","A written warning and a small fine","A 30 day suspension of your license","A free alcohol class and no other penalty"],"why":"Any measurable alcohol while restricted brings a revocation of one year."},{"id":"alc-7nqm26","q":"Under implied consent, by driving in Utah you agree to:","a":"A chemical test if you are arrested for DUI","o":["A chemical test if you are arrested for DUI","Never to have a single drink","To have your car searched on request","To take a vision test every year"],"why":"Refusing the test brings a longer revocation."},{"id":"alc-1enb5u6","q":"A driver under 21 refuses a chemical test for the first time. How long is the revocation?","a":"2 years","o":["2 years","18 months","6 months","1 year"],"why":"Refusal by a driver under 21 is 2 years the first time."},{"id":"alc-dbbnrv","q":"Under a law starting January 1, 2026, what does an interdicted person card do?","a":"Bars buying alcohol and has a red NO ALCOHOL SALE banner","o":["Bars buying alcohol and has a red NO ALCOHOL SALE banner","Lets you buy alcohol after a short class","Lets you drive at night only with a parent","Waives all fines after a DUI conviction"],"why":"Courts may designate DUI convicts as interdicted persons so they cannot buy alcohol."},{"id":"alc-1y49o8q","q":"A plea held in abeyance for a DUI:","a":"Still counts as a prior offense","o":["Still counts as a prior offense","Is erased","Never counts","Only counts after five years"],"why":"It may not show on the record but still counts as a prior."},{"id":"alc-yfks1f","q":"You are impaired and asleep in the driver's seat with the keys in the car. Can you be charged with DUI?","a":"Yes, for actual physical control","o":["Yes, for actual physical control","No, the car is not moving","No, if the engine is off","Only if you are on a highway"],"why":"A driver can be charged while sitting in the driver's seat with keys, even if the engine is off."},{"id":"alc-10z1gy1","q":"A first DUI in Utah is usually a:","a":"Class B misdemeanor","o":["Class B misdemeanor","Felony","Infraction","Class C misdemeanor"],"why":"A first DUI is a Class B misdemeanor in most cases."},{"id":"alc-13xpxzg","q":"Can you be charged with DUI for driving after taking a legal prescription drug?","a":"Yes, if it impairs your driving","o":["Yes, if it impairs your driving","No, because it is legal","No, if you have a prescription","Only on freeways"],"why":"Prescription and over-the-counter drugs can cause a DUI if they impair you."},{"id":"alc-6upzd6","q":"Driving without a required ignition interlock may lead to:","a":"Impoundment and revocation","o":["Impoundment and revocation","A thank you note and a free tow home","A written warning that you can ignore","Nothing, if you drive only a short way"],"why":"It can bring impoundment of the vehicle and a revocation."}]},{"id":"conditions","name":"Distractions & Weather","icon":"⛈️","src":"Handbook: Distractions & Driving Challenges","qs":[{"id":"con-1nxsy99","q":"Drivers under 18 may use a handheld phone only for:","a":"Emergencies, hazards, crime, or calling a parent","o":["Emergencies, hazards, crime, or calling a parent","Navigation, music, and quick text replies","Calls to friends while stopped at lights","Any hands-free call to a classmate"],"why":"Under 18, only emergency, hazard, criminal activity, or parent or guardian calls."},{"id":"con-1lyhhia","q":"Drivers 18 and older may use a phone only by:","a":"Voice commands","o":["Voice commands","Typing at red lights","Holding it low","Texting short replies"],"why":"No manual texting, dialing, or browsing while driving."},{"id":"con-tjzr0n","q":"Texting while driving in Utah is:","a":"A Class C misdemeanor with up to a $100 fine","o":["A Class C misdemeanor with up to a $100 fine","A minor infraction with a $20 fine","A written warning for a first offense","A felony that carries jail time"],"why":"It is a Class C misdemeanor, and Class B if someone is hurt or there is a prior."},{"id":"con-14403ph","q":"If something distracts you, such as pets or children, you should:","a":"Pull over to deal with it","o":["Pull over to deal with it","Reach back while you drive","Slow down to ten mph and fix it","Ignore it until the trip ends"],"why":"Pull over to handle any distraction."},{"id":"con-135jidy","q":"Fatigue tips from the handbook include stopping about how often on long trips?","a":"Every 2 hours","o":["Every 2 hours","Every 6 hours","Every 30 minutes","Once per trip"],"why":"Stop every two hours and avoid late-night driving."},{"id":"con-nwnz2j","q":"How much moving water can carry away most vehicles, including SUVs and pickups?","a":"2 feet","o":["2 feet","6 inches","1 foot","4 feet"],"why":"Six inches can stall a car, and 2 feet of moving water can sweep one away."},{"id":"con-sv75jk","q":"Your car goes into deep water. What is the first move?","a":"Unbuckle your seat belt and lower the window","o":["Unbuckle your seat belt and lower the window","Call 911 and wait inside the car for help","Open the door and swim out right away","Wait until the car fills with water first"],"why":"A car may float only 30 to 60 seconds. Unbuckle and get out."},{"id":"con-sv4f5n","q":"When your rear wheels skid, you should:","a":"Ease off the gas and steer into the skid","o":["Ease off the gas and steer into the skid","Slam on the brakes and hold the wheel","Steer away from the direction of the skid","Accelerate to pull out of the skid"],"why":"Ease off, steer toward the skid direction, and straighten as traction returns."},{"id":"con-w2r8p5","q":"On a long mountain downgrade you should:","a":"Use a lower gear, never coast in neutral","o":["Use a lower gear, never coast in neutral","Coast in neutral to save your brakes","Ride the brakes the whole way down","Shut off the engine to save fuel"],"why":"Gear down and never coast in neutral."},{"id":"con-1cegrw3","q":"On a narrow mountain road, who yields on a downhill?","a":"The downhill driver yields to uphill traffic","o":["The downhill driver yields to uphill traffic","The uphill driver yields to downhill traffic","The faster driver yields to the slower one","The smaller vehicle yields to the larger"],"why":"Downhill traffic yields to uphill traffic."},{"id":"con-14li15b","q":"A large animal runs onto the road ahead. You should:","a":"Brake without swerving","o":["Brake without swerving","Swerve hard to avoid it","Speed up to get past it","Honk and drive faster"],"why":"Do not swerve. Slow down and stay in your lane."},{"id":"con-obkix7","q":"During lightning you are safest:","a":"In a hard-topped vehicle with windows closed","o":["In a hard-topped vehicle with windows closed","Standing next to your car on the road","Under a large tree beside the road","Holding on to the car's antenna"],"why":"A closed, hard-topped car protects you."},{"id":"con-rt18lg","q":"Stranded in cold weather, how long should you run the engine?","a":"About 10 minutes each hour","o":["About 10 minutes each hour","All night to keep the car warm","30 seconds each hour only","Never, because of exhaust fumes"],"why":"Run it about 10 minutes an hour with a window slightly open and the exhaust clear."},{"id":"con-f6h8wu","q":"In hot weather, how often should you check your tires?","a":"Every 2 hours or 100 miles","o":["Every 2 hours or 100 miles","Once a week at the pump","Only when a tire looks low","Only before a long trip"],"why":"Do not release air from hot tires."},{"id":"con-14c67ws","q":"No workers are visible in a work zone. You should:","a":"Still slow down and obey the signs","o":["Still slow down and obey the signs","Speed up to clear the zone faster","Pass slow cars in the work zone","Ignore the signs until you see workers"],"why":"Slow down even without workers."},{"id":"con-b80leg","q":"Which of these is careless driving?","a":"A moving violation while searching for something in the car","o":["A moving violation while searching for something in the car","Driving the speed limit on a clear dry day","Parking in a marked stall near a store","Making a hands-free call with voice commands"],"why":"Careless driving includes a moving violation while distracted by something inside the vehicle."},{"id":"con-1e6risg","q":"A first road rage conviction can lead to:","a":"A one year license suspension","o":["A one year license suspension","A parking ticket and a short warning","A written warning and no other penalty","A $5 fine and a change of plates"],"why":"The court may order a one year suspension for a first road rage enhancement."},{"id":"con-obrh3j","q":"Which is illegal for a driver 18 or older?","a":"Typing a text message by hand","o":["Typing a text message by hand","Using voice commands for a call","Using hands-free navigation","Listening to the radio"],"why":"Manual writing, sending, or reading messages and browsing are banned."},{"id":"con-ttxsl8","q":"A texting while driving conviction is a Class B misdemeanor when:","a":"It causes bodily injury or is a repeat offense","o":["It causes bodily injury or is a repeat offense","It happens in the daytime on a city street","It happens in a parking lot with no other cars","It happens on a freeway in light traffic"],"why":"It is usually Class C. It is Class B when someone is hurt or it is a repeat."},{"id":"con-usg5cm","q":"When are animals most likely to be on the road?","a":"At dawn and dusk","o":["At dawn and dusk","At noon","At midnight only","Only in winter"],"why":"Be extra careful at dawn and dusk."},{"id":"con-1kx0j3s","q":"Driving through the hot desert, what should you carry?","a":"Water for you and the radiator","o":["Water for you and the radiator","Extra tires and a full set of tools","Heavy blankets for the hot days","A small tent with a pair of boots"],"why":"Carry water for yourself and for the radiator."},{"id":"con-s2rbfa","q":"You break down in the desert. What should you do?","a":"Stay with your vehicle","o":["Stay with your vehicle","Walk to find help","Take a side road","Hitchhike"],"why":"Do not wander from a broken-down vehicle."},{"id":"con-19l45j7","q":"How much sleep should adults aim for each night?","a":"7 to 9 hours","o":["7 to 9 hours","3 to 4 hours","5 hours","12 hours"],"why":"Aim for 7 to 9 hours to avoid drowsy driving."},{"id":"con-w2ib1t","q":"If you feel tired while driving, a short nap of about how long can help?","a":"20 minutes","o":["20 minutes","2 hours","5 minutes","All night"],"why":"A 20 minute nap helps. Stop every 2 hours too."},{"id":"con-pxg7g9","q":"You cannot remember the last few miles you drove. This is a sign of:","a":"Drowsiness","o":["Drowsiness","Good focus","Hunger","Good weather"],"why":"Missing recent miles is a sign of fatigue."},{"id":"con-1haklb1","q":"How deep can water be before most cars may lose control or stall?","a":"About 6 inches","o":["About 6 inches","About 2 feet","About 4 feet","About 10 feet"],"why":"Six inches can cause loss of control or stalling. Two feet can sweep away most vehicles."},{"id":"con-7ht0mn","q":"You come to a flooded road. What should you do?","a":"Turn around and find another route","o":["Turn around and find another route","Drive through slowly in the center of the road","Speed through so the water splashes less","Follow a big truck through the water"],"why":"Turn around, do not cross flooded roads."},{"id":"con-f84lfw","q":"Your car is sinking and the window will not open. What should you do?","a":"Wait for the pressure to equalize, then kick out the window","o":["Wait for the pressure to equalize, then kick out the window","Stay put in your seat until help finds you","Keep honking the horn until help arrives","Open the door with all your strength right now"],"why":"Water pressure keeps the door shut. Once pressure equalizes, kick the window out."},{"id":"con-meef6r","q":"You have a long drive in hot weather. What should you watch?","a":"Tire pressure, coolant, and oil","o":["Tire pressure, coolant, and oil","Only the radio and the air conditioning","Only the paint and your tire brand","Only your fuel gauge and the clock"],"why":"Check tire pressure every 2 hours or 100 miles and watch coolant and oil."},{"id":"con-c6qyg6","q":"You are stranded in your car in the snow. What should you do?","a":"Stay with the car and run the engine about 10 minutes each hour","o":["Stay with the car and run the engine about 10 minutes each hour","Walk to find help","Run the engine nonstop","Sleep with the doors locked and all windows up"],"why":"Stay put, clear the exhaust pipe, keep one window open a little, and run the engine about 10 minutes an hour."},{"id":"con-qsdzur","q":"Why keep a window open a little and the exhaust clear when running the engine in the snow?","a":"To prevent carbon monoxide from building up","o":["To prevent carbon monoxide from building up","To cool the engine while it is running","To save gas while you sit and wait","To keep falling snow out of the car"],"why":"Exhaust fumes can enter the car if the pipe is blocked."},{"id":"con-3j8sg7","q":"Your car breaks down on the road. Who should you call?","a":"911","o":["911","A friend only","A tow truck only","No one"],"why":"Call 911 and place flares or triangles 200 to 300 feet behind your car."},{"id":"con-mtom99","q":"During lightning, you should avoid:","a":"Touching metal parts of the car","o":["Touching metal parts of the car","Closing the windows in the vehicle","Staying inside the hard-topped car","Wearing your safety belt in the seat"],"why":"Stay in a hard-topped car with doors closed and windows up. Avoid metal surfaces."},{"id":"con-1vo1sv0","q":"On a narrow mountain road with blind sharp curves, you should:","a":"Honk and stay right","o":["Honk and stay right","Speed up","Drive in the middle","Stop in the lane"],"why":"Honk before blind sharp curves on narrow mountain roads and stay right."},{"id":"con-1h0hp75","q":"You drive on a gravel road. What should you do?","a":"Slow down and increase your following distance","o":["Slow down and increase your following distance","Speed up so the stones fly less","Brake hard and often to test traction","Drive close behind the car ahead"],"why":"Gravel is slippery, so slow down and give more space."},{"id":"con-ydfmo9","q":"Your engine suddenly loses power while driving. What should you do?","a":"Grip firmly, steer, brake gently, and pull off","o":["Grip firmly, steer, brake gently, and pull off","Take your hands off so the wheel can settle","Slam the brakes at once and stop in place","Turn off the key and coast without steering"],"why":"Keep control of the wheel, brake gently, and move off the road."},{"id":"con-1jj5rwp","q":"During a skid, you should NOT:","a":"Slam on the brakes","o":["Slam on the brakes","Ease off the gas","Steer toward the skid","Straighten when you regain traction"],"why":"Slamming the brakes can make a skid worse."},{"id":"con-1f53bfo","q":"Which of these counts as a distraction?","a":"Anything that takes your mind or body off driving","o":["Anything that takes your mind or body off driving","Only phone calls and text messages","Only talking passengers in the back seat","Only eating food while you are driving"],"why":"A distraction is anything that takes your mind or body off driving."},{"id":"con-1buj8jr","q":"You are very angry. What should you do before you drive?","a":"Cool off first","o":["Cool off first","Drive fast to calm down","Turn up the radio","Race to your destination"],"why":"Cool off before driving when you are angry or excited."},{"id":"con-x1iuek","q":"You feel impatient about being late. What helps?","a":"Leave earlier next time","o":["Leave earlier next time","Speed up","Tailgate","Run the red light"],"why":"The handbook says leave early when you are impatient."},{"id":"con-1oj7k8c","q":"Before a long trip, you should check:","a":"Tires, fluids, belts, hoses, brakes, and lights","o":["Tires, fluids, belts, hoses, brakes, and lights","Only your radio and cup holders","Only the paint and the license plate","Only your phone and the air freshener"],"why":"Check key parts before you go."}]},{"id":"crash","name":"Crashes & Insurance","icon":"💥","src":"Handbook: Crashes & Insurance","qs":[{"id":"cra-1comep7","q":"After a crash you should first:","a":"Stop immediately","o":["Stop immediately","Drive home and call","Wait to see if anyone calls you","Move a mile down the road"],"why":"Leaving the scene is a crime."},{"id":"cra-1jpw77u","q":"You must notify police after a crash with injury, death, or at least how much property damage?","a":"$2,500","o":["$2,500","$500","$1,000","$10,000"],"why":"Call 911 for injury, death, or $2,500 or more in damage."},{"id":"cra-2pif94","q":"Failing to stop at a crash with injuries is:","a":"A third-degree felony","o":["A third-degree felony","A traffic infraction with a fine","A warning for first offenders","A misdemeanor with community service"],"why":"It is a felony."},{"id":"cra-5dpfbi","q":"After a crash you must exchange:","a":"Name, address, registration, and insurance","o":["Name, address, registration, and insurance","Phone numbers and employer details","Driver license and Social Security numbers","Only your name and license plate number"],"why":"Share name, address, vehicle registration number, and insurance details."},{"id":"cra-1a4uvbg","q":"You hit an unattended parked car and cannot find the owner. You should:","a":"Leave a note with your name and address","o":["Leave a note with your name and address","Drive away if no one saw the damage","Leave only your phone number on a note","Wait one hour, then drive away"],"why":"Leave a note with your name and address."},{"id":"cra-pax2fv","q":"After a property-damage-only crash, you may:","a":"Move your car out of the travel lanes","o":["Move your car out of the travel lanes","Leave both cars where they stopped","Swap seats so the owner drives","Remove your license plates first"],"why":"Move to a safe place if possible."},{"id":"cra-1z54yk","q":"Where should you place breakdown flares or triangles?","a":"200 to 300 feet behind the vehicle","o":["200 to 300 feet behind the vehicle","About 20 feet behind the vehicle","About 50 feet in front of the vehicle","Right beside the driver's door"],"why":"Flares and triangles go 200 to 300 feet back."},{"id":"cra-5ygth0","q":"Your brakes fail. What do you try first?","a":"Apply the parking brake slowly","o":["Apply the parking brake slowly","Turn off the engine right away","Shift into reverse immediately","Steer toward oncoming traffic"],"why":"If that fails, shut off the engine and stop well off the road."},{"id":"cra-gtt4w4","q":"Your accelerator sticks. You should:","a":"Shift to neutral, steer, and brake gently","o":["Shift to neutral, steer, and brake gently","Turn off the engine at high speed","Brake as hard as you can at once","Shift to park and coast to a stop"],"why":"Shift to neutral and pull off."},{"id":"cra-1euyo2i","q":"A front tire blows out while you drive. What should you do?","a":"Hold the wheel firmly and slow down gradually","o":["Hold the wheel firmly and slow down gradually","Brake hard and steer away from the tire","Accelerate to keep the car going straight","Take your hands off the wheel and coast"],"why":"Hold the wheel steady and slow gradually."},{"id":"cra-a0gyjb","q":"With ABS brakes on a slippery road, you should:","a":"Press firmly and hold the pedal","o":["Press firmly and hold the pedal","Pump the pedal several times","Tap the brakes in short bursts","Use only the parking brake"],"why":"A pulsing pedal is normal. Keep pressure on."},{"id":"cra-1m3bw4h","q":"Which coverage does Utah law require?","a":"Liability and personal injury protection","o":["Liability and personal injury protection","Collision and comprehensive coverage","Roadside assistance and towing","Rental reimbursement coverage"],"why":"Liability and PIP are mandatory. Collision and comprehensive are optional."},{"id":"cra-dyohb2","q":"Proof of insurance must be:","a":"In the vehicle and shown on request","o":["In the vehicle and shown on request","Kept at home and mailed in yearly","Shown only when you renew the plates","Carried only if the car is financed"],"why":"Electronic proof is allowed."},{"id":"cra-15xwzv3","q":"If a wheel drops off the pavement edge, you should:","a":"Slow down gradually and return to the road","o":["Slow down gradually and return to the road","Yank the wheel hard back onto the road","Brake hard before you steer back","Speed up to climb back on quickly"],"why":"Do not panic. Slow gradually and steer back on."},{"id":"cra-3qdpij","q":"Leaving the scene of a crash can bring a fine of up to:","a":"$2,500","o":["$2,500","$100","$500","$10,000"],"why":"The handbook lists a jail sentence up to 1 year and a fine up to $2,500, plus a license suspension or revocation."},{"id":"cra-5his61","q":"Someone seems badly hurt after a crash. Should you move them?","a":"Not unless it prevents more injury","o":["Not unless it prevents more injury","Yes, right away to the shoulder","Yes, into your car to keep them warm","Yes, so the road stays open for traffic"],"why":"Do not move a seriously hurt person unless needed to prevent further injury."},{"id":"cra-gp9os7","q":"After a crash, what help must you give to hurt people?","a":"Reasonable help, like arranging a ride to a hospital","o":["Reasonable help, like arranging a ride to a hospital","None, you must stay inside your own car","Only calling a friend to come and help","Driving them yourself without calling anyone"],"why":"You must give reasonable help, including arranging transport if treatment is apparent or requested."},{"id":"cra-n50voe","q":"You gave your information to a police officer at the scene. Do you also need to give it to the other drivers?","a":"No, giving it to the officer meets the requirement","o":["No, giving it to the officer meets the requirement","Yes, you must also give it to each driver","Yes, in writing within a week","Yes, but only by phone later that day"],"why":"Giving the information to the officer at the scene covers you."},{"id":"cra-1l5jhyo","q":"A crash causes $1,500 in damage and no one is hurt. What must you do?","a":"Exchange your information","o":["Exchange your information","Call 911 only and then leave","Leave quickly since it is small","Do nothing since no one is hurt"],"why":"911 is required for injury, death, or $2,500 or more in damage. You must always exchange information."},{"id":"cra-1geiy1c","q":"Knowingly driving without required insurance is a:","a":"Class B misdemeanor","o":["Class B misdemeanor","Felony","Parking ticket","Warning"],"why":"It is a class B misdemeanor and can cost you your license, registration, and plates."},{"id":"cra-17u4q61","q":"After a crash, a judgment for damages is not paid. How long before your driving privileges may be suspended?","a":"60 days","o":["60 days","7 days","1 year","10 days"],"why":"If a court judgment is unpaid for 60 days, driving privileges are suspended."},{"id":"cra-jrsae9","q":"How long must SR22 'future proof' insurance be kept after a suspension or revocation?","a":"3 years","o":["3 years","1 year","6 months","10 years"],"why":"SR22 must be kept for 3 years."},{"id":"cra-1yqv2wd","q":"Your vehicle is found to be uninsured. How long do you have to buy insurance before registration is revoked?","a":"30 days","o":["30 days","6 months","90 days","1 year"],"why":"Registration is revoked unless insurance is bought within 30 days."},{"id":"cra-19bkmsp","q":"Which coverage pays for damage to your own car in a crash, but is not required by Utah law?","a":"Collision","o":["Collision","Liability","Personal injury protection","Uninsured motorist"],"why":"Collision covers your car and is not required by law, though lenders often require it."},{"id":"cra-h2cf9d","q":"Which coverage pays for fire, theft, vandalism, or glass damage?","a":"Comprehensive","o":["Comprehensive","Collision","Liability","Personal injury protection"],"why":"Comprehensive covers non-collision damage."},{"id":"cra-qn98q0","q":"Uninsured motorist coverage protects you when:","a":"An uninsured or hit-and-run driver hurts you","o":["An uninsured or hit-and-run driver hurts you","You hit a tree on a snowy road","You get a speeding ticket in town","Your tire goes flat on a highway"],"why":"It covers you and your passengers if an uninsured or hit-and-run driver causes the crash."},{"id":"cra-36mb5d","q":"Personal injury protection (no-fault) pays benefits:","a":"No matter who caused the crash","o":["No matter who caused the crash","Only to the at-fault driver","Only if you are not hurt","Only for property damage"],"why":"PIP pays basic benefits for injury without deciding fault."},{"id":"cra-2pcj6e","q":"Who may require you to carry collision and comprehensive insurance?","a":"A lender or lienholder","o":["A lender or lienholder","The Highway Patrol","The school district","Your neighbor"],"why":"The law does not require them, but a lienholder can."},{"id":"cra-1w6ijdz","q":"You are convicted of driving without insurance or proof. What can you expect?","a":"An SR22 for 3 years","o":["An SR22 for 3 years","A free pass","A warning letter","A check in the mail"],"why":"Conviction brings an SR22 requirement for 3 years and a reinstatement fee."}]},{"id":"points","name":"Points & Penalties","icon":"⚖️","src":"Handbook: Suspensions & Your Record","qs":[{"id":"poi-uczjrt","q":"A driver under 21 can face a hearing at how many points in 3 years?","a":"70","o":["70","200","100","50"],"why":"Under 21 the threshold is 70 points in three years."},{"id":"poi-16fag1m","q":"A driver 21 or older can face a hearing at how many points in 3 years?","a":"200","o":["200","70","100","300"],"why":"Over 21 it is 200 points in three years."},{"id":"poi-5wmift","q":"Reckless driving is how many points?","a":"80","o":["80","60","50","35"],"why":"Reckless driving is 80 points."},{"id":"poi-qkwmr1","q":"Running a red light or stop sign is how many points?","a":"50","o":["50","35","60","80"],"why":"Each is 50 points."},{"id":"poi-m798m3","q":"Following too closely or failing to yield is how many points?","a":"60","o":["60","50","40","80"],"why":"Each is 60 points."},{"id":"poi-v35vls","q":"A defensive driving course can remove how many points?","a":"50, once every 3 years","o":["50, once every 3 years","100, once every year","25, any time you ask","All points, once every 3 years"],"why":"Course credit is 50 points, once per 3 years."},{"id":"poi-1w54m2e","q":"Driving while suspended can bring up to:","a":"90 days in jail plus a fine","o":["90 days in jail plus a fine","A warning for a first time","A fine of $20 and no jail","One day in jail, no fine"],"why":"The suspension is also extended by the original period."},{"id":"poi-zhnvw2","q":"Convictions stay on your driving record for how long (non-alcohol)?","a":"3 years","o":["3 years","1 year","5 years","10 years"],"why":"Most show for 3 years. Alcohol and drug violations show for 10."},{"id":"poi-1wema3b","q":"What happens after a Move Over law conviction?","a":"A 4-hour class in 90 days, or a suspension","o":["A 4-hour class in 90 days, or a suspension","A $500 fine and a retake of the road test","A written warning and 20 points added","Community service and a 30-day suspension"],"why":"Take the class or the license is suspended 90 days."},{"id":"poi-2td46o","q":"How many points can a speeding violation carry?","a":"35 to 75, depending on how bad it is","o":["35 to 75, depending on how bad it is","Always 10, no matter how fast","Always 100, no matter how slow","Always 200, even for small speeding"],"why":"Speeding points range from 35 to 75."},{"id":"poi-qmd119","q":"Texting while driving adds how many points?","a":"50","o":["50","10","80","200"],"why":"Texting while driving is 50 points."},{"id":"poi-173dhpj","q":"Driving on the wrong side of the road is how many points?","a":"60","o":["60","10","30","200"],"why":"Wrong side of the road and wrong way on a one-way street are 60 points each."},{"id":"poi-ow88ht","q":"Improper passing or improper lookout is how many points?","a":"50","o":["50","20","60","80"],"why":"Both are 50 points."},{"id":"poi-1ayoajq","q":"Most other moving violations carry how many points?","a":"40","o":["40","5","90","200"],"why":"Other moving violations are 40 points."},{"id":"poi-1s0jre8","q":"After one full year with no moving violation conviction, what happens to your points?","a":"Half are removed","o":["Half are removed","All are removed","None are removed","They double"],"why":"Half your total points are removed after a clean year."},{"id":"poi-8bfas9","q":"After two straight years with no conviction, what happens to your points?","a":"All are removed","o":["All are removed","Half are removed","None are removed","Only 10 are removed"],"why":"All points are cleared after two clean years."},{"id":"poi-qgp3lb","q":"Points from an individual violation drop off after:","a":"3 years","o":["3 years","1 year","6 months","10 years"],"why":"Points drop off 3 years after the violation date."},{"id":"poi-168u5jt","q":"What can happen after a point hearing?","a":"Probation, a defensive driving course, or suspension","o":["Probation, a defensive driving course, or suspension","Nothing at all, since hearings are optional","A free license renewal for two years","A lifetime ban in every case"],"why":"Outcomes depend on your record and range from probation to suspension."},{"id":"poi-1gsgxgn","q":"Which action brings a mandatory license revocation?","a":"Fleeing from a police signal","o":["Fleeing from a police signal","A single parking ticket downtown","One speeding ticket on a freeway","Forgetting to signal at a turn"],"why":"Fleeing an officer is a mandatory revocation."},{"id":"poi-1vcasdi","q":"You do not show up in court for a traffic ticket. What can happen?","a":"Your license may be suspended","o":["Your license may be suspended","Nothing","The ticket is canceled","You get extra points off"],"why":"Failing to appear can lead to a suspension."},{"id":"poi-qsl4p3","q":"You ignore a ticket from another state that belongs to the Non-Resident Violator Compact. What can happen in Utah?","a":"Your Utah license can be suspended","o":["Your Utah license can be suspended","Nothing, since it is out of state","Your plates change","You lose your passport"],"why":"Utah can suspend your license for failing to answer a ticket in an NRVC state."},{"id":"poi-1wtpl3r","q":"Under 21 drivers have which kind of point system?","a":"A separate provisional point system","o":["A separate provisional point system","The same one as everyone else","No points at all for any ticket","A system run by a parent"],"why":"Provisional Class D licenses use a separate point system."},{"id":"poi-1o48gyt","q":"Driving on a suspension that was alcohol related can bring a fine up to:","a":"$1,000 and up to 6 months in jail","o":["$1,000 and up to 6 months in jail","$50 and a warning letter","$100 and a defensive driving class","$10,000 and 5 years in jail"],"why":"The handbook lists a fine up to $1,000 and up to six months in jail."},{"id":"poi-181rmnp","q":"Which of these is a mandatory revocation?","a":"Not stopping to help after a crash that hurts someone","o":["Not stopping to help after a crash that hurts someone","A first speeding ticket on a state road","A parking ticket in a downtown lot","A broken tail light found at a stop"],"why":"Leaving the scene of an injury crash is a mandatory revocation."}]},{"id":"share","name":"Sharing the Road","icon":"🚲","src":"Handbook: Sharing the Road","qs":[{"id":"sha-6buix5","q":"When you pass a bicyclist, how much space must you leave?","a":"At least 3 feet","o":["At least 3 feet","At least 1 foot","At least 5 feet","Enough to avoid touching"],"why":"Give bicyclists at least 3 feet and slow down."},{"id":"sha-9ht1ae","q":"You may stop, park, or drive in a marked bike lane (solid white line) only:","a":"Only to enter a driveway or in an emergency","o":["Only to enter a driveway or in an emergency","Only to pass slow traffic ahead of you","Only to wait for a gap to turn","Only to drop off or pick up riders"],"why":"Otherwise stay out of the bike lane."},{"id":"sha-1n4g1e9","q":"Before you open your car door or back up you should:","a":"Check for bicyclists","o":["Check for bicyclists","Honk","Signal","Roll down the window"],"why":"Doors opened into bike traffic cause crashes."},{"id":"sha-8wjall","q":"At night you should dim your headlights within how far of a bicyclist?","a":"500 feet","o":["500 feet","100 feet","1,000 feet","50 feet"],"why":"Dim lights within 500 feet of a bicyclist."},{"id":"sha-w0jdwa","q":"Bicyclists on the road have:","a":"The same rules as drivers","o":["The same rules as drivers","No rules","Only rules for sidewalks","Right-of-way in all cases"],"why":"Bicyclists follow the same traffic rules."},{"id":"sha-1yq2laj","q":"Pedestrians can be hard to see when you turn. You should:","a":"Slow down, look twice, and yield","o":["Slow down, look twice, and yield","Honk and turn before they step out","Turn quickly so you clear the crosswalk","Wait for them to look at you first"],"why":"Many pedestrian crashes happen during turns."},{"id":"sha-3qsmv4","q":"How much of a lane do motorcycles deserve?","a":"A full lane","o":["A full lane","Half a lane","Whatever is left","The shoulder"],"why":"Never share a lane with a motorcycle."},{"id":"sha-1s18gbe","q":"A motorcycle's turn signal is flashing. You should:","a":"Not assume it is turning","o":["Not assume it is turning","Assume it is about to turn","Pass it on the right quickly","Speed up to get ahead of it"],"why":"Motorcycle signals often do not cancel."},{"id":"sha-1hxg9pn","q":"How far back should you follow a motorcycle?","a":"At least 2 seconds, more when wet","o":["At least 2 seconds, more when wet","Just one second, even when wet","One car length, even in the rain","Bumper to bumper in slow traffic"],"why":"Riders can brake and swerve fast."},{"id":"sha-1tos4hr","q":"Utah lane filtering is only legal for a motorcycle going:","a":"15 mph or less","o":["15 mph or less","25 mph or less","5 mph or less","45 mph or less"],"why":"Filtering also needs a stopped vehicle in the lane and a safe gap. Splitting is illegal."},{"id":"sha-1z0w5qp","q":"Motorcycle riders and passengers under what age must wear a helmet?","a":"21","o":["21","18","16","25"],"why":"Under 21 means a DOT approved helmet."},{"id":"sha-1kj4m4j","q":"If you cannot see a truck driver in the side mirror:","a":"The driver cannot see you","o":["The driver cannot see you","You are safe","You are in the no-zone only at night","You are too close but it is fine"],"why":"The no-zone includes sides, rear, and front."},{"id":"sha-z3xcv2","q":"After passing a truck you should:","a":"Wait to see its whole front in your mirror","o":["Wait to see its whole front in your mirror","Pull in as soon as you are alongside it","Cut in quickly to avoid its blind spot","Brake hard in front of it to be seen"],"why":"Make sure there is plenty of room."},{"id":"sha-h549tl","q":"Why do trucks swing left before a right turn?","a":"Their long trailers need extra room","o":["Their long trailers need extra room","The driver cannot see the right side","They are trying to hog the lane","They must avoid the curb signs"],"why":"Never squeeze between a truck and the curb."},{"id":"sha-1pqk2sc","q":"An emergency vehicle with flashing lights approaches. You should:","a":"Pull to the right and stop","o":["Pull to the right and stop","Stop right where you are","Pull to the left and stop","Keep driving at your speed"],"why":"Move to the right edge and stop until it passes."},{"id":"sha-1o85un","q":"You may follow a fire engine responding to an alarm no closer than:","a":"500 feet","o":["500 feet","100 feet","50 feet","1,000 feet"],"why":"Do not follow one closer than 500 feet."},{"id":"sha-moqo2j","q":"The Move Over law tells you to:","a":"Slow down and change lanes away from it","o":["Slow down and change lanes away from it","Stop behind it and wait for it to leave","Pass it quickly on the shoulder side","Speed up to clear the area fast"],"why":"Move over or slow down for stationary hazard vehicles."},{"id":"sha-1yoxc0x","q":"A school bus on a two-lane road has flashing red lights. Who stops?","a":"Traffic in both directions","o":["Traffic in both directions","Only the traffic behind it","Only the oncoming traffic","Nobody, if there is no sign"],"why":"On two-lane roads both directions stop."},{"id":"sha-119vfjp","q":"A school bus on a divided highway with a median has flashing red lights. Who stops?","a":"Only vehicles behind the bus","o":["Only vehicles behind the bus","Traffic in both directions","Only the oncoming traffic","Nobody, if the median is wide"],"why":"With a median, only traffic behind the bus stops."},{"id":"sha-1xigc59","q":"An orange triangle on the back of a vehicle means it travels:","a":"Under 25 mph","o":["Under 25 mph","Over 55 mph","Only at night","Only on farm roads"],"why":"A slow-moving vehicle emblem."},{"id":"sha-1tmzodz","q":"Passing a horse and rider you should:","a":"Pass with care, not honk or rev","o":["Pass with care, not honk or rev","Honk once to warn the horse","Rev your engine to signal them","Pass quickly to clear the area"],"why":"Noise can spook animals."},{"id":"sha-1jr8jt3","q":"A police officer pulls you over. You should:","a":"Pull right, stop safely, and keep your hands on the wheel","o":["Pull right, stop safely, and keep your hands on the wheel","Keep driving until you find a well-lit road","Get out and walk back to the officer's car","Stay in your lane and flash your lights"],"why":"Park, turn the engine off, and stay put."},{"id":"sha-dbqgcj","q":"The operator of farm machinery on the road:","a":"May not hear your vehicle","o":["May not hear your vehicle","Is required to pull over for you","Can see behind well from the cab","Will always move to the shoulder"],"why":"Pass with care."},{"id":"sha-184sx25","q":"How are dedicated bike lanes marked?","a":"With solid white lines","o":["With solid white lines","With dashed yellow lines","With red cones","With green paint only"],"why":"Dedicated bike lanes are marked with solid white lines."},{"id":"sha-v8fvrh","q":"When may you sound your horn close to a bicyclist?","a":"Only if a crash is likely","o":["Only if a crash is likely","Whenever you pass one","Never, under any rule","To say hello to a rider"],"why":"Avoid honking near bicyclists unless a crash is likely."},{"id":"sha-2ts70w","q":"You are about to pass a bicyclist but a hill crest blocks your view. What should you do?","a":"Do not pass","o":["Do not pass","Pass quickly","Honk and pass","Pass on the right"],"why":"Do not pass a bicyclist near the crest of a hill or a curve with a blocked view."},{"id":"sha-nugnjc","q":"You may not pass a bicycle within what distance of an intersection or railroad crossing?","a":"100 feet","o":["100 feet","10 feet","50 feet","300 feet"],"why":"Do not pass within 100 feet of an intersection or railroad crossing."},{"id":"sha-102qd6d","q":"A bicyclist keeps both hands on the handlebars and does not signal a turn. Why?","a":"They may need both hands to stay in control","o":["They may need both hands to stay in control","They forgot how to give a signal","Signals are against the law for bicyclists","They did not plan to turn at all"],"why":"Bicyclists may skip hand signals when road conditions need both hands on the bars."},{"id":"sha-uehvtp","q":"A bicyclist slows at a stop sign, yields to pedestrians, and rolls through. Under Utah's rules this is:","a":"Allowed","o":["Allowed","A ticket","Illegal in every case","A felony"],"why":"Bicyclists may proceed slowly without stopping if they yield to pedestrians."},{"id":"sha-lmm2xu","q":"How many bicyclists may ride side by side on a Utah road?","a":"No more than two","o":["No more than two","Up to five","As many as want","Only one"],"why":"Bicyclists must ride with traffic and no more than two abreast."},{"id":"sha-j65g2t","q":"A Class 1 electric-assisted bicycle gives pedal assist only up to:","a":"20 mph","o":["20 mph","10 mph","28 mph","35 mph"],"why":"Class 1 is pedal-assist only and cuts off at 20 mph. Class 3 cuts off at 28 mph."},{"id":"sha-109z0q9","q":"A bicycle must be able to stop how quickly?","a":"Within 25 feet from 10 mph","o":["Within 25 feet from 10 mph","Within 5 feet from 5 mph","Within 100 feet from 30 mph","Within 50 feet from 20 mph"],"why":"The brake must stop it within 25 feet from 10 mph."},{"id":"sha-pk21on","q":"What does a bicyclist need at night?","a":"A white headlight, red taillight or reflector, side reflectors","o":["A white headlight, red taillight or reflector, side reflectors","A horn and a siren for warning drivers","A loud bell and a rear flag only","Nothing, if there are street lights"],"why":"Night riding needs a white headlight, red taillight or reflector, and side reflectors seen from 500 feet."},{"id":"sha-h524y5","q":"A bicycle, by Utah's definition, has wheels at least what diameter?","a":"14 inches","o":["14 inches","6 inches","10 inches","30 inches"],"why":"Bicycles have wheels at least 14 inches across."},{"id":"sha-geij","q":"A bicyclist rides slowly on a sidewalk. What must the rider do?","a":"Yield to pedestrians and give a sound signal before passing","o":["Yield to pedestrians and give a sound signal before passing","Speed up to get past the walkers quickly","Ride in the crosswalk without slowing down","Ignore pedestrians since bikes have priority"],"why":"On sidewalks, bicyclists must ride slowly, yield, and signal before passing."},{"id":"sha-1jux4hc","q":"A bicyclist on a road with three or more lanes is going slowly. May you use the center left-turn lane to pass?","a":"Yes, if the cyclist is below a reasonable speed","o":["Yes, if the cyclist is below a reasonable speed","No, the center lane is for left turns only","Only at night when there is less traffic","Only if the bicyclist waves you through"],"why":"The handbook allows it on roads with three or more lanes."},{"id":"sha-zrt8wb","q":"You pass a bicyclist and want to turn right soon after. What should you not do?","a":"Turn sharply in front of them","o":["Turn sharply in front of them","Slow down and watch for them","Check your mirrors before turning","Signal well ahead of the turn"],"why":"Do not turn sharply in front of a bicyclist or force them off the road."},{"id":"sha-ii4ibb","q":"Where should a pedestrian walk if there is no sidewalk?","a":"On the left shoulder, facing traffic","o":["On the left shoulder, facing traffic","On the right shoulder with traffic","In the middle of the lane","Behind parked cars"],"why":"Walk on the left shoulder, as far from the road as possible, facing traffic."},{"id":"sha-cvjn6y","q":"A school traffic patrol member is signaling you. What should you do?","a":"Stop and yield","o":["Stop and yield","Slow down and pass","Honk","Speed up"],"why":"Stop and yield where a school traffic patrol is signaling."},{"id":"sha-1f42u9m","q":"Most pedestrian deaths in Utah happen at what time?","a":"In the evening, around 9 p.m.","o":["In the evening, around 9 p.m.","At noon on school days","At 6 a.m. as people go to work","Around 3 p.m. after school ends"],"why":"The highest hour is 9 p.m., then 10 p.m., 6 p.m., 7 p.m., and 8 p.m."},{"id":"sha-jfw70k","q":"A leading driver factor in Utah pedestrian deaths is:","a":"Failing to yield right-of-way","o":["Failing to yield right-of-way","Driving too slowly in the right lane","Using high beams in the daytime","Using hazard lights on city streets"],"why":"Failing to yield and improper turning were leading factors."},{"id":"sha-85pruz","q":"Riders on motorcycles may swerve suddenly because of:","a":"Potholes, gravel, seams, or railroad crossings","o":["Potholes, gravel, seams, or railroad crossings","Left turn signals from cars ahead","Clear roads with wide lanes","Warm weather and dry pavement"],"why":"Riders may swerve for road hazards, so give them room."},{"id":"sha-mcfkty","q":"A large truck has a front no-zone of about:","a":"20 feet","o":["20 feet","2 feet","200 feet","5 feet"],"why":"Truck blind spots reach up to 20 feet in front of the cab."},{"id":"sha-1pozflp","q":"A large truck has a rear no-zone that can reach:","a":"Up to 200 feet","o":["Up to 200 feet","Up to 20 feet","Up to 5 feet","Up to 2 feet"],"why":"The blind spot behind a trailer can reach 200 feet."},{"id":"sha-1ttamia","q":"Which side of a truck has the biggest blind spot?","a":"The right side","o":["The right side","The left side","The front only","The back only"],"why":"The right side is the truck's largest blind spot."},{"id":"sha-1k2hpxs","q":"A tractor-trailer going 55 mph and fully loaded may need more than what distance to stop?","a":"400 feet","o":["400 feet","50 feet","130 feet","200 feet"],"why":"A car at 55 mph stops in about 130 to 140 feet. A loaded tractor-trailer may need over 400."},{"id":"sha-4mc8k3","q":"When you meet a large truck on a two-lane road you should:","a":"Move as far right as you can","o":["Move as far right as you can","Move toward the center line to give room","Brake hard to let the truck pass","Flash your lights to get its attention"],"why":"Wind blasts from trucks can push you, so move right."},{"id":"sha-1vy24q5","q":"You see a single lane work zone ahead and a truck is beside you. What should you not do?","a":"Try to beat the truck into the zone","o":["Try to beat the truck into the zone","Slow down and stay behind the line","Follow the flagger directions","Let the truck go first"],"why":"Do not try to beat a truck into a single-lane construction zone."},{"id":"sha-1sbfg2m","q":"Most deadly crashes involving a truck and another vehicle are caused by:","a":"The other vehicle, usually a car","o":["The other vehicle, usually a car","The truck driver, usually from speeding","The weather, usually from heavy rain","The road, usually from construction"],"why":"NHTSA says 71 percent are caused by the other vehicle."},{"id":"sha-kil9j","q":"A large vehicle is stopped on a hill ahead of you. What should you watch for?","a":"Stalling or rolling backward","o":["Stalling or rolling backward","It speeding up fast on the hill","It honking at you to get closer","Nothing, since trucks never roll back"],"why":"Stay back in case it stalls or rolls back."},{"id":"sha-9hjr4l","q":"A school bus has flashing yellow lights. This means:","a":"It is about to stop, so slow down","o":["It is about to stop, so slow down","It has stopped, so you may pass at speed","It is leaving the road for a break","It is a signal to speed up and pass"],"why":"Yellow lights warn that the bus is getting ready to stop."},{"id":"sha-3tl4hc","q":"A school bus has flashing red lights on a four-lane road with no median. Who must stop?","a":"Traffic in both directions","o":["Traffic in both directions","Only traffic behind the bus","Only traffic coming toward the bus","No one"],"why":"Without a median, traffic in both directions must stop."},{"id":"sha-1xvg3j0","q":"A school bus stops with flashing red lights on a road with five lanes, including a center turn lane. Who must stop?","a":"Only vehicles behind the bus","o":["Only vehicles behind the bus","Traffic in both directions","Only vehicles coming toward the bus","No one"],"why":"With five or more lanes, oncoming traffic does not have to stop."},{"id":"sha-je0o8y","q":"When may you go after a school bus stops with flashing red lights?","a":"When the lights stop and the stop arm is in","o":["When the lights stop and the stop arm is in","When the bus driver waves you around","After counting to ten seconds","As soon as the children have crossed"],"why":"Do not proceed until the lights stop flashing."},{"id":"sha-1hfp6xn","q":"A police officer signals you to stop while you are in the HOV or express lane. What should you do?","a":"Pull to the right, even through the other lanes","o":["Pull to the right, even through the other lanes","Stop in the lane where you are driving","Speed up and find a place on the left","Pull to the left shoulder if it is closer"],"why":"Pull to the right and stop, even if you are in an HOV lane."},{"id":"sha-nojqox","q":"During a police stop, you should keep your seat belt:","a":"On","o":["On","Off","Half on","Off, so you can reach your papers"],"why":"Park, turn off the engine, lower the window, keep your belt on, and keep your hands on the wheel."},{"id":"sha-1779bsz","q":"You approach a stationary vehicle with amber lights while in the HOV lane. What should you do?","a":"Leave the HOV lane when practical","o":["Leave the HOV lane when practical","Speed up","Stay in the lane at the same speed","Honk"],"why":"Move out of the HOV lane when practical."},{"id":"sha-wvl0fi","q":"Golf cart operators may not:","a":"Drink alcohol while driving","o":["Drink alcohol while driving","Wear a seat belt","Use headlights","Drive on private roads"],"why":"Golf cart operators follow bicycle rules and may never drink alcohol while operating."},{"id":"sha-16k2ixj","q":"A farm tractor is on the road. How should you pass?","a":"With care, since the operator may not hear you","o":["With care, since the operator may not hear you","Quickly while honking your horn loudly","Around the right side only, at high speed","Never, so you must follow it for miles"],"why":"Farm machinery operators may not hear your vehicle, so pass with care."}]},{"id":"rail","name":"Railroads & Light Rail","icon":"🚆","src":"Handbook: Trains & Railroad Crossings","qs":[{"id":"rai-1wnd8uq","q":"How far from the nearest rail should you stop at a crossing?","a":"15 to 50 feet from the nearest rail","o":["15 to 50 feet from the nearest rail","5 to 10 feet from the nearest rail","75 to 100 feet from the nearest rail","Right at the edge of the rail"],"why":"Stop 15 to 50 feet back."},{"id":"rai-rjrpnu","q":"Flashing red lights at a crossing mean:","a":"Stop, and do not go while they flash","o":["Stop, and do not go while they flash","Slow down and cross when it looks clear","Yield to the cars on the cross road","Proceed if you cannot see a train"],"why":"Always stop."},{"id":"rai-1odw7ki","q":"The gates at a crossing are down. You may:","a":"Wait until they rise and lights stop","o":["Wait until they rise and lights stop","Go around them if no train is seen","Drive under them slowly and carefully","Cross quickly before the train arrives"],"why":"Never drive around or under a gate."},{"id":"rai-5gly03","q":"When a train and a vehicle meet, who has the right-of-way?","a":"The train, every time","o":["The train, every time","The larger vehicle","Emergency vehicles","The first one to the crossing"],"why":"Trains have the right-of-way, even over ambulances and police."},{"id":"rai-16eh8jl","q":"Your car stalls on the tracks. What do you do first?","a":"Get everyone out and away from the tracks","o":["Get everyone out and away from the tracks","Try to restart the engine first","Stay inside and wait for tow help","Honk the horn to warn the train"],"why":"People first. Move away from the tracks at an angle, away from the train."},{"id":"rai-1hgv20a","q":"How much room does a 100-car freight train at 55 mph need to stop?","a":"More than a mile","o":["More than a mile","About 100 yards","About 500 feet","About 2 football fields"],"why":"Trains cannot stop quickly."},{"id":"rai-c64saq","q":"A flashing train logo at an intersection is:","a":"A warning only; obey the signals and signs","o":["A warning only; obey the signals and signs","A signal to stop before the tracks","A signal that a train is approaching","A sign to yield to the train"],"why":"The flashing train logo is only a warning."},{"id":"rai-3xzvqj","q":"With light rail (TRAX) you should:","a":"Never try to beat it through the crossing","o":["Never try to beat it through the crossing","Cross fast because light rail is slow","Follow the car ahead across the tracks","Stop on the tracks if traffic is backed up"],"why":"Wait until gates rise and the lights stop."},{"id":"rai-tktdkj","q":"You should never stop:","a":"On the tracks","o":["On the tracks","Behind the gate","Before the crossing","At a stop line"],"why":"Make sure you can fully clear the tracks."},{"id":"rai-g1brq9","q":"Which vehicles must stop at every railroad crossing?","a":"School buses and hazmat trucks","o":["School buses and hazmat trucks","Only commercial trucks and buses","Only motorcycles and bicycles","Only vehicles with trailers"],"why":"They also never shift gears on the crossing."},{"id":"rai-cqwun3","q":"At a crossing you should never:","a":"Pass a vehicle going your direction","o":["Pass a vehicle going your direction","Slow down and look both ways","Turn the radio down to listen","Stop behind the line and wait"],"why":"Never pass at a crossing."},{"id":"rai-1v2onbo","q":"A train looks like it is moving slowly. You should know that:","a":"It is closer and faster than it seems","o":["It is closer and faster than it seems","It is as slow as it appears","It will stop before the crossing","It is probably very far away"],"why":"Trains are quieter and faster than they look."},{"id":"rai-1ko8l8b","q":"Where may you walk on railroad tracks?","a":"Nowhere, it is illegal and dangerous","o":["Nowhere, it is illegal and dangerous","Anywhere if you watch for trains","Only at night when lights show","Only if you are with a group"],"why":"Tracks are private property."},{"id":"rai-1t9uz4x","q":"You approach a crossing. What should you do with the radio?","a":"Turn it down so you can hear","o":["Turn it down so you can hear","Turn it up","Leave it alone","Turn it off at night only"],"why":"Turn down the radio at crossings so you can hear a train."},{"id":"rai-1yrqfqa","q":"It is night and you do not see a train. May you assume none is coming?","a":"No, trains can come at any time","o":["No, trains can come at any time","Yes, because trains do not run at night","Yes, after midnight when schedules end","Only on weekdays when freight runs"],"why":"Do not assume no train is coming at night."},{"id":"rai-18pwqqf","q":"A TRAX light rail train can reach 65 mph in about how long?","a":"21 seconds","o":["21 seconds","2 minutes","5 minutes","10 minutes"],"why":"TRAX reaches 65 mph in about 21 seconds, so it covers distance fast."},{"id":"rai-rv91l3","q":"How far past the rails can a train reach?","a":"3 feet or more","o":["3 feet or more","6 inches","About 1 inch","None"],"why":"Trains can extend three feet or more outside the rails."},{"id":"rai-1cndk3p","q":"A train has just passed. When may you cross?","a":"When the gates are up and the lights have stopped","o":["When the gates are up and the lights have stopped","As soon as the last car passes the road","Right away if you honk your horn first","After a short wait of five seconds"],"why":"Wait until gates rise and lights stop flashing."},{"id":"rai-10pp2um","q":"A train has just passed but the lights keep flashing. What should you do?","a":"Wait, because another train may be coming","o":["Wait, because another train may be coming","Cross at once since the first train passed","Drive around the gates to save time","Honk and go once you see no train"],"why":"Always check for another train, especially at multi-track crossings."},{"id":"rai-1y17su5","q":"Your car stalls on the tracks and a train is coming. Where should you run?","a":"Away from the tracks at an angle","o":["Away from the tracks at an angle","Toward the train so it can see you","Back into the car to wait for help","Along the tracks in the same direction"],"why":"Get everyone out and run away from the tracks at an angle."},{"id":"rai-1phoqkm","q":"Your car is stuck on the tracks. Who should you notify?","a":"The authorities","o":["The authorities","No one","A friend","A mechanic only"],"why":"Notify the authorities after you get everyone out."},{"id":"rai-1h2ucib","q":"A railroad crossing has no stop line. Where do you stop?","a":"15 to 50 feet from the nearest rail","o":["15 to 50 feet from the nearest rail","Right on the tracks","Within 5 feet of the rail","100 feet away"],"why":"Stop more than 15 feet and not more than 50 feet from the nearest rail."},{"id":"rai-1lewwb1","q":"A crossing has a flashing train logo on an overhead sign. What does it mean?","a":"It is a warning only","o":["It is a warning only","The crossing is closed","It is safe","Train is passing now"],"why":"The train logo is a warning. Follow the signals and signs."}]},{"id":"equip","name":"Equipment & Towing","icon":"🔧","src":"Handbook: Vehicle Equipment & Towing","qs":[{"id":"equ-17w5z4i","q":"High beam headlights must light the road about how far?","a":"350 feet","o":["350 feet","100 feet","500 feet","1,000 feet"],"why":"Low beams reach about 100 feet."},{"id":"equ-jztmwt","q":"Your horn must be heard from at least:","a":"200 feet","o":["200 feet","50 feet","500 feet","1,000 feet"],"why":"Horns must be audible from 200 feet."},{"id":"equ-1g4s5eu","q":"Tail lights and stop lights must be visible from:","a":"500 feet","o":["500 feet","100 feet","200 feet","1,000 feet"],"why":"Rear lights must show from 500 feet."},{"id":"equ-aj1jl9","q":"Which of these may you hang from your mirror or windshield?","a":"Nothing that blocks your view","o":["Nothing that blocks your view","Anything under four inches long","Only a parking permit or tag","Only a small air freshener"],"why":"Windshield must be clear of obstruction."},{"id":"equ-dne20f","q":"Red or blue lights visible from the front are for:","a":"Only emergency and other authorized vehicles","o":["Only emergency and other authorized vehicles","Any large truck or tow truck on a call","Taxis and rideshare drivers at night","Delivery vans working in busy traffic"],"why":"Others may not use them."},{"id":"equ-a92xqg","q":"Sirens, whistles, and bells are for:","a":"Authorized emergency vehicles only","o":["Authorized emergency vehicles only","Any vehicle in an emergency","Trucks over 10,000 pounds","School buses and city buses"],"why":"Keep them off personal vehicles."},{"id":"equ-1xftktl","q":"A drawbar between two vehicles can be at most:","a":"15 feet","o":["15 feet","5 feet","25 feet","50 feet"],"why":"Rope or chain tows need a flag at least 12 inches square."},{"id":"equ-1lhg5hm","q":"A load extending 4 feet or more past the vehicle needs:","a":"Flags or lights on the end","o":["Flags or lights on the end","A police escort in front","A horn on the load","Nothing if it is secured"],"why":"Use red flags by day and lights at night."},{"id":"equ-csfgcj","q":"Is a fire extinguisher legally required in a car?","a":"No, but it is recommended","o":["No, but it is recommended","Yes, in every passenger car","Yes, in cars with trailers","Yes, in cars over five years old"],"why":"Recommended for all drivers."},{"id":"equ-13g4mv2","q":"What is the maximum width of most vehicles?","a":"8 and a half feet","o":["8 and a half feet","7 and a half feet","9 and a half feet","10 and a half feet"],"why":"Farm tractors may be 9 feet."},{"id":"equ-1jfvith","q":"Driver assist features like lane keeping mean you:","a":"Must stay engaged and keep sensors clean","o":["Must stay engaged and keep sensors clean","Can let the car drive itself on any road","Can look away from the road briefly","Can skip your head check on lane changes"],"why":"You are still the driver."},{"id":"equ-16cqk1j","q":"Which vehicles must have a parking brake?","a":"All except motorcycles","o":["All except motorcycles","Only trucks and buses","Only vehicles with a stick shift","Only vehicles over 3,000 pounds"],"why":"One working parking brake is required."},{"id":"equ-1m0njat","q":"How many white headlights does a car need?","a":"At least two, one on each side","o":["At least two, one on each side","One","Four","None if there are fog lights"],"why":"At least two white headlights, one per side."},{"id":"equ-mxqsv","q":"Your license plate light must make the plate readable from:","a":"50 feet","o":["50 feet","10 feet","500 feet","5 feet"],"why":"The light must make the plate readable from 50 feet."},{"id":"equ-19ow3qt","q":"Turn signals must be visible from:","a":"100 feet","o":["100 feet","10 feet","500 feet","1,000 feet"],"why":"Turn signals must be visible from 100 feet."},{"id":"equ-1etbijl","q":"Parking lights on the front of a car are:","a":"White or amber","o":["White or amber","Red or blue","Green or purple","Blue or green"],"why":"Parking lights in front are white or amber."},{"id":"equ-1glp2mk","q":"How many windshield wipers must a vehicle have at least?","a":"One","o":["One","Two","Three","None"],"why":"At least one working wiper is required."},{"id":"equ-1i2490s","q":"A towed vehicle must have:","a":"A safety chain or cable","o":["A safety chain or cable","A siren and a flashing light","A radio and a loud horn","A bumper sticker with a warning"],"why":"Towed vehicles need safety chains or cables."},{"id":"equ-6ok1x4","q":"A flag on a load that sticks out 4 feet or more must be at least:","a":"12 inches square","o":["12 inches square","1 inch square","6 inches square","48 inches square"],"why":"Flags on the load must be at least 12 inches square."},{"id":"equ-po17ss","q":"Advanced driver assist systems may not work well in:","a":"Rain, snow, ice, fog, hills, or curves","o":["Rain, snow, ice, fog, hills, or curves","Clear dry weather on a flat road","Straight highways in good light","Parking lots on a sunny day"],"why":"Stay engaged, because the systems may fail in bad weather or on curves."},{"id":"equ-1dm02o7","q":"Reflectors on the sides of a vehicle must be seen from:","a":"500 feet","o":["500 feet","50 feet","100 feet","10 feet"],"why":"Reflectors must be visible from 500 feet."},{"id":"equ-1s98ynt","q":"Vehicles that are 80 inches or wider need:","a":"Clearance lights","o":["Clearance lights","Only a horn","Flags only","Nothing extra"],"why":"Wide vehicles need amber front and red rear clearance lights."}]},{"id":"moto","name":"Motorcycles & Small Vehicles","icon":"🏍️","src":"Handbook: Sections 4, 14 (motorcycles, scooters, ATVs)","qs":[{"id":"mot-138rfta","q":"What do you need to ride a motorcycle on Utah highways?","a":"A motorcycle endorsement on your license","o":["A motorcycle endorsement on your license","A boat license and a safety card","A truck permit with an extra stamp","Nothing special beyond a regular license"],"why":"Your driver license must have a motorcycle endorsement (M)."},{"id":"mot-1bger6r","q":"Can a first-time rider get a motorcycle learner permit?","a":"Yes, if you have not been licensed to ride before","o":["Yes, if you have not been licensed to ride before","No, only people who already ride can get one","Only at age 30 and older","Only if you also hold a CDL"],"why":"A person never licensed to ride may be issued a motorcycle learner permit."},{"id":"mot-2jhdt1","q":"How can a rider skip the rider skills part of the motorcycle test?","a":"By finishing a division approved motorcycle course","o":["By finishing a division approved motorcycle course","By paying an extra fee at the counter","By riding only at night for six weeks","They cannot skip it in any case"],"why":"The division may waive the skills test after an approved motorcycle education course."},{"id":"mot-gsycvj","q":"A motorcycle applicant under 18 needs:","a":"A parent or guardian signature","o":["A parent or guardian signature","A school letter and a note from police","A bank statement for a deposit","Nothing, since age does not matter"],"why":"Applicants under 18 need a parent or guardian to sign."},{"id":"mot-1vpvtnd","q":"A street-legal motorcycle in Utah must carry:","a":"Liability insurance","o":["Liability insurance","Only a spare tire","A fire extinguisher","A flag"],"why":"All motorcycles licensed for street use must have liability insurance."},{"id":"mot-1u8cze2","q":"A 19 year old passenger is on the back of a motorcycle. What must the passenger wear?","a":"An approved DOT helmet","o":["An approved DOT helmet","Nothing, since passengers are exempt","Only goggles to protect the eyes","A baseball cap with a chin strap"],"why":"Any operator or passenger under 21 must wear an approved DOT helmet."},{"id":"mot-6e94rl","q":"Lane filtering by a motorcycle is legal only if the rider is going:","a":"15 mph or less","o":["15 mph or less","30 mph or less","45 mph or less","No faster than traffic"],"why":"Lane filtering needs 15 mph or less, a stopped vehicle in the lane, and a safe move."},{"id":"mot-1wjpml7","q":"Lane filtering is allowed only on roads with a speed limit of:","a":"45 mph or less, or on an off-ramp","o":["45 mph or less, or on an off-ramp","65 mph or less on any highway","75 mph or less on the interstate","Any speed if the rider is careful"],"why":"The road must be 45 mph or less, or the rider must be on an off-ramp."},{"id":"mot-1ra1d7q","q":"Where is lane filtering NOT allowed?","a":"On an on-ramp","o":["On an on-ramp","On an off-ramp","On a multi-lane road with a stopped car","On a road posted 35 mph"],"why":"The handbook says it is not permitted on an on-ramp."},{"id":"mot-50s2j4","q":"During lane filtering, the vehicle being passed must be:","a":"Stopped","o":["Stopped","Going 15 mph","Going 45 mph","Signaling"],"why":"The overtaken vehicle must be stopped."},{"id":"mot-1ytsezf","q":"A motorcycle waits at a signal that does not detect it. When may a rider 16 or older go?","a":"After 90 seconds if no one is near, age 16 or older","o":["After 90 seconds if no one is near, age 16 or older","Right away, since the light is broken","After 5 seconds of waiting at the line","Never, the rider must wait for a car"],"why":"Operators 16 or older may go after waiting 90 seconds when it is safe."},{"id":"mot-xywtjm","q":"A rider is caught with no motorcycle endorsement. Under a 2025 law, the fine is waived if:","a":"The rider gets the endorsement within 30 days","o":["The rider gets the endorsement within 30 days","The rider pays double the fine at once","The rider sells the motorcycle right away","The rider only rides during daylight hours"],"why":"HB 234 waives the fine if the endorsement is obtained within 30 days."},{"id":"mot-juyfyd","q":"A motor-assisted scooter rider is under 15. What is required?","a":"Supervision by a parent or guardian","o":["Supervision by a parent or guardian","A helmet and no other requirement","A driver license for scooters","Nothing, since scooters are exempt"],"why":"Riders under 15 must be supervised by a parent or guardian."},{"id":"mot-1gs1vpd","q":"Where may motor-assisted scooters NOT be used?","a":"On highways posted over 25 mph","o":["On highways posted over 25 mph","On a sidewalk with no signs posted","On a quiet neighborhood street","In a private driveway at home"],"why":"They are not allowed on highways posted above 25 mph or with four or more lanes."},{"id":"mot-l3tf4z","q":"A street-legal ATV on a highway may go no faster than:","a":"The posted limit or 50 mph, whichever is less","o":["The posted limit or 50 mph, whichever is less","75 mph on any state highway","The speed of the cars around it","60 mph on all roads"],"why":"The top highway speed is the lesser of the posted limit or 50 mph."},{"id":"mot-1wlvpom","q":"Which license can drive a street-legal ATV, UTV, or FSV?","a":"Class D or a CDL","o":["Class D or a CDL","Learner permit only","A boat license","No license"],"why":"Class D or CDL holders may operate them."},{"id":"mot-1i37o50","q":"A pedestrian vehicle for a person with a disability can go no faster than:","a":"30 mph","o":["30 mph","10 mph","45 mph","60 mph"],"why":"Pedestrian vehicles cannot exceed 30 mph."},{"id":"mot-w4bwz5","q":"A low-speed vehicle is a four-wheeled electric vehicle with a top speed of:","a":"25 mph","o":["25 mph","15 mph","45 mph","65 mph"],"why":"Low-speed vehicles are limited to 25 mph and carry no more than four people."},{"id":"mot-p2w283","q":"A rider under 21 on a street-legal ATV must wear:","a":"A DOT-approved helmet","o":["A DOT-approved helmet","Nothing, since helmets are optional","A cap with a visor only","Gloves and boots only"],"why":"Operators under 21 must wear a DOT approved helmet."},{"id":"mot-13kfusp","q":"Lane splitting is:","a":"Illegal","o":["Illegal","Always legal","Legal on freeways","Legal at night"],"why":"Lane splitting is illegal. Only lane filtering under strict rules is allowed."}]},{"id":"towing","name":"Towing & Warning Devices","icon":"🚛","src":"Handbook: Section 16 (Towing) and loads","qs":[{"id":"tow-z3uktc","q":"A big vehicle is stopped on the road for more than how long before warning devices are required?","a":"10 minutes","o":["10 minutes","1 minute","1 hour","30 minutes"],"why":"Vehicles 80 inches wide or 30 feet long must put out warning devices after 10 minutes."},{"id":"tow-1mxhvqy","q":"Where should you place the first warning device after stopping a wide or long vehicle?","a":"On the side toward oncoming traffic","o":["On the side toward oncoming traffic","Behind the driver seat of the vehicle","In front of the hood of the vehicle","In the glove box until it is dark"],"why":"Place the first device toward oncoming traffic."},{"id":"tow-k7e668","q":"How far should warning devices be placed in front and behind a stopped vehicle?","a":"100 feet","o":["100 feet","10 feet","20 feet","500 feet"],"why":"Place devices 100 feet front and rear."},{"id":"tow-165c6zt","q":"On a one-way street, how far behind your vehicle should you place a rear warning flag?","a":"200 feet","o":["200 feet","20 feet","50 feet","1,000 feet"],"why":"The handbook says 200 feet behind on one-way streets."},{"id":"tow-127yqq7","q":"When are warning devices not needed?","a":"When light shows the vehicle from 1,000 feet","o":["When light shows the vehicle from 1,000 feet","When it is windy outside and cold","When it is raining or snowing","When you are in a hurry to leave"],"why":"They are not needed when light shows the vehicle from 1,000 feet."},{"id":"tow-mzrdjl","q":"How should you handle a flare?","a":"Keep it away from your face and fuel","o":["Keep it away from your face and fuel","Hold it close to your face to see it","Tie it to the bumper so it stays put","Light it near a fuel leak to test it"],"why":"Keep flares away from your eyes and fuel, and do not attach them to the vehicle."},{"id":"tow-2u5dip","q":"What is the best way to put out a tire fire?","a":"Use water","o":["Use water","Use a blanket","Let it burn","Use gasoline"],"why":"Water is the best remedy for tire fires."},{"id":"tow-1ly1gre","q":"You may NOT fight a gasoline or oil fire with:","a":"Water","o":["Water","A fire extinguisher","Dirt","Sand"],"why":"Do not use water on a gasoline or oil fire."},{"id":"tow-1xm01h","q":"When you fight a fire outdoors, where should the wind be?","a":"At your back","o":["At your back","In your face","From the side","It does not matter"],"why":"Fight fires with the wind at your back."},{"id":"tow-1qa863o","q":"How far may a load extend in front of a truck?","a":"3 feet","o":["3 feet","10 feet","1 foot","20 feet"],"why":"Loads may extend no more than 3 feet in front and 6 feet at the rear."},{"id":"tow-n82d17","q":"How far may a load extend behind a truck?","a":"6 feet","o":["6 feet","3 feet","20 feet","50 feet"],"why":"The rear limit is 6 feet."},{"id":"tow-gciys9","q":"A towed car swerves and whips dangerously. What should you do?","a":"Do not tow it that way","o":["Do not tow it that way","Speed up so it settles down","Honk to warn drivers and keep going","Keep going and watch the rear mirror"],"why":"Do not operate a vehicle train when a towed unit whips or swerves."},{"id":"tow-rao4aw","q":"A trailer weighs under 750 pounds empty and is not used for business. Does it need registration?","a":"No","o":["No","Yes, always","Yes, at night","Yes, in winter"],"why":"Trailers under 750 pounds empty that are not used commercially need no registration."},{"id":"tow-fwsu4w","q":"How far apart can two towed vehicles be using a drawbar?","a":"15 feet","o":["15 feet","3 feet","30 feet","50 feet"],"why":"The maximum is 15 feet."},{"id":"tow-kjbm34","q":"What is a flag on a rope or chain tow connection for?","a":"To make it visible to others","o":["To make it visible to others","To decorate the front bumper","To signal a left turn","To cool the engine during towing"],"why":"A red flag at least 12 inches square must be on a chain, rope, or cable connection."}]},{"id":"health","name":"Health, Vision & Appendices","icon":"🩺","src":"Handbook: Section 5 and Appendices","qs":[{"id":"hea-tfhlie","q":"You fail the vision test even with glasses. What do you need?","a":"A statement from your eye doctor","o":["A statement from your eye doctor","A letter from your boss at work","A car with larger side mirrors","Nothing, since glasses are not required"],"why":"If you fail the standard, you need a statement from your eye doctor."},{"id":"hea-uw255e","q":"How often must drivers 65 and older pass a vision test?","a":"With every license application","o":["With every license application","Only once every ten years","Never, since glasses are enough","Only at age 70 and older"],"why":"Everyone 65 and older must pass a vision test with every application."},{"id":"hea-11lxpq3","q":"A health condition may affect your driving. What must you do?","a":"Tell the division and seek a medical evaluation","o":["Tell the division and seek a medical evaluation","Ignore it until it gets worse","Stop driving for the rest of your life","Tell your friends and keep driving"],"why":"You must report it to DLD and get medical evaluation."},{"id":"hea-11vv88q","q":"Can a doctor take away your driving privilege directly?","a":"No, doctors report and the division decides","o":["No, doctors report and the division decides","Yes, doctors can end your license on the spot","Yes, if you ask for it in writing","Yes, for a period of up to 30 days"],"why":"Physicians report health status accurately but cannot restrict driving themselves."},{"id":"hea-zy9ylk","q":"What does the Driver License Medical Advisory Board focus on?","a":"Functional ability to drive","o":["Functional ability to drive","Your age and your last name","Your income and your car type","Your school grades and your job"],"why":"It focuses on functional driving ability, not just impairments."},{"id":"hea-1dwbkpb","q":"Does a review examination automatically take away your license?","a":"No, drivers often keep driving with restrictions","o":["No, drivers often keep driving with restrictions","Yes, the license is taken at the end","Yes, for one year in every review","Yes, for life once a review is ordered"],"why":"A review does not automatically remove privileges."},{"id":"hea-mlgqi0","q":"Which is a warning sign of an emotional problem that affects driving?","a":"Constant anger at other drivers","o":["Constant anger at other drivers","Wearing a seat belt","Driving the speed limit","Using turn signals"],"why":"Constant anger at other drivers is a warning sign."},{"id":"hea-gnj2fs","q":"One organ donor can save up to how many lives?","a":"Eight","o":["Eight","Two","20","100"],"why":"One donor can save up to eight lives, and tissue donors help over 75 people."},{"id":"hea-qnohwv","q":"A tissue donor can help over how many people?","a":"75","o":["75","7","10","500"],"why":"Tissue donors can help over 75 people."},{"id":"hea-zigw7w","q":"Organ recovery costs the donor's family:","a":"Nothing","o":["Nothing","The hospital bill","$5,000","The funeral bill"],"why":"Organ recovery costs the donor's family nothing."},{"id":"hea-hlob1d","q":"How long should you let a car idle before turning it off to cut pollution?","a":"Turn it off if idling will last more than 30 seconds","o":["Turn it off if idling will last more than 30 seconds","Idle for ten minutes before you turn it off","Never turn it off in cold weather","Idle for an hour to warm the engine"],"why":"Turn the engine off if you expect to idle over 30 seconds."},{"id":"hea-1jv2vn6","q":"Identity fraud in Utah is:","a":"A felony","o":["A felony","A parking ticket","A written warning only","Legal if you return the card"],"why":"Identity fraud is a felony under Utah law."},{"id":"hea-225shs","q":"Submitting fake documents to the Driver License Division will result in:","a":"Prosecution","o":["Prosecution","A warning letter","A reminder to retake the test","No penalty if it is a first try"],"why":"Fraudulent documents are prosecuted."},{"id":"hea-lye5az","q":"How many emergency contacts may you list with the division?","a":"Up to two","o":["Up to two","Only one","Ten","None"],"why":"You may list up to two individuals in the emergency contact database."},{"id":"hea-1b1o74l","q":"Medications can cause drowsiness. What should you do?","a":"Ask a doctor whether it is safe to drive","o":["Ask a doctor whether it is safe to drive","Take a double dose and then drive","Drink coffee and drive as usual","Ignore the drowsiness and keep driving"],"why":"A doctor may advise against driving until the dose is safe."}]}];
